const MILES_PER_METER=1/1609.344, supported=['FIT','TCX','GPX'];
const APP_VERSION='0.5.3';
function Logo(){return <div className="brand"><div className="mark">EF</div><div><strong>ENDURANCE FORGE</strong><span>ADVANCED RUNNING ANALYTICS</span></div></div>}
const pagePaths={home:'/',analyze:'/analyze/',compare:'/compare/',guide:'/metrics/',method:'/methodology/',science:'/science/'};
const pathPages={'/':'home','/analyze':'analyze','/analyze/':'analyze','/compare':'compare','/compare/':'compare','/metrics':'guide','/metrics/':'guide','/methodology':'method','/methodology/':'method','/science':'science','/science/':'science'};
const pageMeta={
 home:{title:'Endurance Forge | Advanced Running Analytics',description:'Analyze FIT, TCX, and GPX running activities locally in your browser. Explore pace, heart rate, running dynamics, physiological response, multi-run patterns, and specialized treadmill analytics.'},
 analyze:{title:'Run Analyzer | Endurance Forge',description:'Analyze a running activity locally in your browser. Endurance Forge provides detailed physiological and running-dynamics analysis with specialized treadmill workload tools.'},
 compare:{title:'Multi-Run Analysis | Endurance Forge',description:'Analyze multiple treadmill runs, outdoor runs, or any combination of both. Explore individualized patterns in physiological response, performance, and running dynamics while keeping treadmill-specific calculations appropriately separated.'},
 guide:{title:'Running Metrics Guide | Endurance Forge',description:'Learn how Endurance Forge interprets aerobic fitness estimates, running oxygen cost, HR drift, heart-rate reserve, stable analysis windows, and data quality.'},
 method:{title:'Analysis Methodology | Endurance Forge',description:'Read the Endurance Forge methodology for single-run and robust multi-run aerobic fitness inference, workload oxygen cost, heart-rate reserve, and drift.'},
 science:{title:'Scientific Basis of the EF Aerobic Fitness Estimate | Endurance Forge',description:'Technical justification, derivation, evidence, limitations, and peer-reviewed references for the Endurance Forge submaximal treadmill aerobic-fitness estimate.'}
};
function pageFromLocation(){return pathPages[window.location.pathname]||'home'}
function Shell({children,page,go}){return <div className="app"><header><Logo/><nav><button className={page==='home'?'active':''} onClick={()=>go('home')}>Home</button><button className={page==='analyze'?'active':''} onClick={()=>go('analyze')}>Analyze Run</button><button className={page==='compare'?'active':''} onClick={()=>go('compare')}>Multi-Run Analysis</button><button className={page==='guide'?'active':''} onClick={()=>go('guide')}>Metrics Guide</button><button className={page==='method'?'active':''} onClick={()=>go('method')}>Methodology</button><button className={page==='science'?'active':''} onClick={()=>go('science')}>Scientific Basis</button></nav><div className="privacy">PUBLIC BETA · v{APP_VERSION} · LOCAL-FIRST</div></header><main>{children}</main><footer><Logo/><div className="footer-center"><p>Endurance Forge is a public beta. Metrics are analytical estimates, not device-manufacturer metrics or laboratory measurements.</p><a className="coffee-button footer-coffee" href="https://buymeacoffee.com/enduranceforge" target="_blank" rel="noreferrer">☕ Buy the developer a coffee</a></div><span>v{APP_VERSION} · FIT · TCX · GPX processed locally</span></footer></div>}
function FormatChips(){return <div className="format-chips">{supported.map(x=><span key={x}>{x}</span>)}</div>}
function Home({go}){return <><section className="hero"><div className="eyebrow">ADVANCED RUNNING ANALYTICS</div><h1>Your run is more than a device summary.</h1><p>Explore the data behind your running. Endurance Forge analyzes FIT, TCX, and GPX activities to reveal patterns in pace, heart rate, running dynamics, physiological response, and performance across outdoor and treadmill runs — while keeping your raw activity files in your browser.</p><FormatChips/><div className="hero-actions"><button className="primary" onClick={()=>go('analyze')}>Analyze a run</button><button className="secondary" onClick={()=>go('compare')}>Multi-Run Analysis</button></div><div className="trust"><span>✓ Outdoor + treadmill running</span><span>✓ Browser-local processing</span><span>✓ Running dynamics + physiological response</span><span>✓ Specialized treadmill analytics</span></div></section><section className="feature-grid"><article><div className="icon">01</div><h3>Analyze the run</h3><p>FIT, TCX, and GPX are normalized into one running-data model so analysis is not tied to one watch, platform, or file format.</p></article><article><div className="icon">02</div><h3>Understand the response</h3><p>Go beyond pace and distance with heart-rate response, drift, running dynamics, workout structure, and data-quality context.</p></article><article><div className="icon">03</div><h3>Find patterns across runs</h3><p>Compare treadmill runs, outdoor runs, or both. Multi-run views keep unlike conditions appropriately separated while exposing trends in your own data.</p></article></section><section className="banner"><div><div className="eyebrow">DEEPER TREADMILL ANALYTICS</div><h2>Running analytics for every run, with treadmill-specific tools for corrected distance and time, grade-aware workload, indoor environment, and EF aerobic-fitness estimation.</h2></div><button className="secondary" onClick={()=>go('method')}>See the methodology</button></section></>}
function DropZone({onFiles,multiple=false,title='Drop an activity file here'}){const[drag,setDrag]=useState(false);return <label className={'drop '+(drag?'drag':'')} onDragEnter={()=>setDrag(true)} onDragLeave={()=>setDrag(false)} onDrop={()=>setDrag(false)}><input type="file" multiple={multiple} onChange={e=>{const files=[...e.target.files];onFiles(files);e.target.value=''}}/><div className="upload-icon">⇧</div><strong>{title}</strong><span>or click to browse · FIT, TCX, GPX</span><FormatChips/><small>File type is validated after selection · processed locally in this browser</small></label>}
function Metric({label,value,sub,tone=''}){return <div className={'metric '+tone}><span>{label}</span><strong>{value}</strong>{sub&&<small>{sub}</small>}</div>}
function Capabilities({activity}){return <div className="cap-grid">{capabilityRows(activity).map(([n,ok])=><div className={'cap '+(ok?'yes':'no')} key={n}><b>{ok?'✓':'—'}</b><span>{n}</span></div>)}</div>}
function safeMiles(a){return a?.capabilities.distance?a.recordedDistanceM*MILES_PER_METER:NaN}
function safeTime(a){return a?.capabilities.duration?a.recordedTimerS:NaN}
function parseClock(v){if(!v)return NaN;const p=v.trim().split(':').map(Number);if(p.some(Number.isNaN))return NaN;if(p.length===3)return p[0]*3600+p[1]*60+p[2];if(p.length===2)return p[0]*60+p[1];const n=Number(v);return Number.isFinite(n)?n:NaN}
function fmtMph(v){return Number.isFinite(v)?v.toFixed(2)+' mph':'—'}
function confidenceClass(c){return c==='High'?'good':c==='Moderate'?'moderate':c==='Low'?'low':''}

function fileInputKey(f){return f?`ef-run-input:${f.name}:${f.size||0}:${f.lastModified||0}`:''}
function readRunPrefs(f){try{return JSON.parse(localStorage.getItem(fileInputKey(f))||'{}')||{}}catch{return {}}}
function writeRunPrefs(f,v){if(!f)return;try{localStorage.setItem(fileInputKey(f),JSON.stringify(v))}catch{}}
function meanFinite(values){const a=values.filter(Number.isFinite);return a.length?a.reduce((x,y)=>x+y,0)/a.length:NaN}
function fmtPaceFromMph(mph){if(!(mph>0))return '—';const sec=3600/mph,m=Math.floor(sec/60),ss=Math.round(sec%60);return `${m}:${String(ss===60?0:ss).padStart(2,'0')}${ss===60?'*':''}/mi`}
function distAtTime(series,t){if(!series?.length)return NaN;let best=series[0];for(const r of series){if(Math.abs(r.t-t)<Math.abs(best.t-t))best=r;}return best.distanceMi}
function GradeConfirmation({grade}){const g=Number(grade);return <div className={'grade-confirm '+(g===0?'warn':'ok')}>{g===0?'⚠ Grade is 0.0% — confirm the treadmill was level.':`✓ Grade ${Number.isFinite(g)?g.toFixed(1):grade}% included in workload calculations.`}</div>}


function toCelsius(v,unit='F'){const n=Number(v);if(!Number.isFinite(n))return NaN;return unit==='C'?n:(n-32)*5/9}
function fromCelsius(c,unit='F'){return unit==='C'?c:c*9/5+32}
function dewPointC(tempC,rh){if(!Number.isFinite(tempC)||!(rh>0&&rh<=100))return NaN;const a=17.625,b=243.04,g=Math.log(rh/100)+(a*tempC)/(b+tempC);return b*g/(a-g)}
function environmentSummary(env){
 const sC=toCelsius(env?.startTemp,env?.tempUnit),eC=toCelsius(env?.endTemp,env?.tempUnit),sRh=Number(env?.startRh),eRh=Number(env?.endRh);
 const sd=dewPointC(sC,sRh),ed=dewPointC(eC,eRh),hasStart=Number.isFinite(sC)&&Number.isFinite(sRh),hasEnd=Number.isFinite(eC)&&Number.isFinite(eRh);
 if(!hasStart&&!hasEnd)return {available:false};
 const representativeDew=meanFinite([sd,ed]),representativeTemp=meanFinite([sC,eC]);
 let context='Environmental conditions recorded for context.';
 if(Number.isFinite(representativeDew)){context=representativeDew>=21?'Very humid conditions may increase cardiovascular strain.':representativeDew>=18?'Humid conditions may contribute to cardiovascular strain.':representativeDew>=13?'Moderate atmospheric moisture was present.':'Relatively dry conditions were recorded.'}
 if(Number.isFinite(representativeTemp)&&representativeTemp>=26.5)context='Warm indoor conditions. '+context;
 return {available:true,startC:sC,endC:eC,startRh:sRh,endRh:eRh,startDewC:sd,endDewC:ed,dewPointC:representativeDew,tempC:representativeTemp,tempChangeC:Number.isFinite(sC)&&Number.isFinite(eC)?eC-sC:NaN,rhChange:Number.isFinite(sRh)&&Number.isFinite(eRh)?eRh-sRh:NaN,context};
}
function fmtTempC(c,unit='F'){if(!Number.isFinite(c))return '—';return `${fromCelsius(c,unit).toFixed(1)}°${unit}`}
function EnvironmentPanel({tempUnit,setTempUnit,startTemp,setStartTemp,startRh,setStartRh,endTemp,setEndTemp,endRh,setEndRh}){
 const env=environmentSummary({tempUnit,startTemp,startRh,endTemp,endRh});
 const[open,setOpen]=useState(()=>env.available);
 const switchUnit=(u)=>{if(u===tempUnit)return;const cv=v=>{const c=toCelsius(v,tempUnit);return Number.isFinite(c)?fromCelsius(c,u).toFixed(1):v};setStartTemp(cv(startTemp));setEndTemp(cv(endTemp));setTempUnit(u)};
 return <div className={'panel environment-panel '+(open?'open':'collapsed')}><button type="button" className="collapse-head" onClick={()=>setOpen(v=>!v)} aria-expanded={open}><div className="panel-head collapse-panel-head"><div><span>ENV</span><h2>Environment <small className="optional-label">optional</small></h2></div><div className="collapse-summary"><small>{env.available?'Conditions entered':'Indoor/treadmill context'}</small><b>{open?'−':'+'}</b></div></div></button>{open&&<div className="collapse-body"><div className="environment-toolbar"><label className="temp-unit">Temperature <select value={tempUnit} onChange={e=>switchUnit(e.target.value)}><option value="F">°F</option><option value="C">°C</option></select></label></div><div className="environment-grid"><div><b>Start</b><label>Temperature<input value={startTemp} onChange={e=>setStartTemp(e.target.value)} inputMode="decimal" placeholder={tempUnit==='F'?'e.g. 72.0':'e.g. 22.2'}/></label><label>Relative humidity (%)<input value={startRh} onChange={e=>setStartRh(e.target.value)} inputMode="decimal" placeholder="e.g. 45"/></label></div><div><b>End</b><label>Temperature<input value={endTemp} onChange={e=>setEndTemp(e.target.value)} inputMode="decimal" placeholder={tempUnit==='F'?'e.g. 74.0':'e.g. 23.3'}/></label><label>Relative humidity (%)<input value={endRh} onChange={e=>setEndRh(e.target.value)} inputMode="decimal" placeholder="e.g. 50"/></label></div></div>{env.available&&<div className="environment-result"><div><span>Start dew point</span><b>{fmtTempC(env.startDewC,tempUnit)}</b></div><div><span>End dew point</span><b>{fmtTempC(env.endDewC,tempUnit)}</b></div><div><span>Temperature change</span><b>{Number.isFinite(env.tempChangeC)?`${env.tempChangeC>=0?'+':''}${(tempUnit==='F'?env.tempChangeC*9/5:env.tempChangeC).toFixed(1)}°${tempUnit}`:'—'}</b></div><div><span>Humidity change</span><b>{Number.isFinite(env.rhChange)?`${env.rhChange>=0?'+':''}${env.rhChange.toFixed(0)} pp`:'—'}</b></div><p>{env.context} Environment is interpretive context and does not alter the EF Aerobic Fitness Estimate.</p></div>}<p className="note">Use room conditions for indoor/treadmill runs. These values stay in this browser with the run's treadmill inputs and can help interpret HR drift and compare similar workloads across runs.</p></div>}</div>
}

function PaceHrProgression({analysis,runType='treadmill'}){
 const rows=(analysis?.series||[]).filter(r=>Number.isFinite(r.distanceMi)&&(Number.isFinite(r.hr)||Number.isFinite(r.speedMph)));
 if(rows.length<10)return null;
 const data=rows.length>700?rows.filter((_,i)=>i%Math.ceil(rows.length/700)===0):rows;
 const W=1000,H=290,L=58,R=62,T=26,B=46,maxX=Math.max(...data.map(r=>r.distanceMi),.1);
 const hrs=data.map(r=>r.hr).filter(Number.isFinite),paces=data.map(r=>r.speedMph>0?60/r.speedMph:NaN).filter(Number.isFinite);
 const minHr=Math.floor((Math.min(...hrs)-5)/5)*5,maxHr=Math.ceil((Math.max(...hrs)+5)/5)*5;
 const minP=Math.max(4,Math.floor(Math.min(...paces)-1)),maxP=Math.ceil(Math.max(...paces)+1);
 const x=v=>L+(v/maxX)*(W-L-R),yh=v=>H-B-((v-minHr)/Math.max(1,maxHr-minHr))*(H-T-B),yp=v=>T+((v-minP)/Math.max(1,maxP-minP))*(H-T-B);
 const path=(key,fn)=>data.filter(r=>Number.isFinite(key(r))).map((r,i)=>(i?'L':'M')+x(r.distanceMi).toFixed(1)+' '+fn(key(r)).toFixed(1)).join(' ');
 const ticks=[0,.25,.5,.75,1].map(q=>q*maxX);
 const fs=analysis.fitnessWindow?distAtTime(rows,analysis.fitnessWindow.startS):NaN,fe=analysis.fitnessWindow?distAtTime(rows,analysis.fitnessWindow.endS):NaN;
 return <div className="viz-card progression-card"><div className="viz-head"><div><span>PACE + HEART RATE PROGRESSION</span><strong>{runType==='treadmill'?'See the physiological response across corrected treadmill distance':'See pace and cardiovascular response across recorded distance'}</strong></div><small>{runType==='treadmill'?'fitness window shaded':'outdoor recorded distance'}</small></div><svg viewBox={`0 0 ${W} ${H}`}>{ticks.map((v,i)=><g key={i}><line className="chart-grid" x1={x(v)} y1={T} x2={x(v)} y2={H-B}/><text className="chart-text tick-label" x={x(v)} y={H-B+18} textAnchor="middle">{v.toFixed(v<1?2:1)} mi</text></g>)}{runType==='treadmill'&&Number.isFinite(fs)&&Number.isFinite(fe)&&<rect className="fitness-shade" x={x(fs)} y={T} width={Math.max(2,x(fe)-x(fs))} height={H-T-B}/>}<line className="chart-axis" x1={L} y1={H-B} x2={W-R} y2={H-B}/><path className="hr-line strong-line" d={path(r=>r.hr,yh)}/><path className="pace-line" d={path(r=>r.speedMph>0?60/r.speedMph:NaN,yp)}/><text className="axis-side hr-axis" x="8" y="18">HR {minHr}–{maxHr} bpm</text><text className="axis-side pace-axis" x={W-8} y="18" textAnchor="end">Pace {minP}:00–{maxP}:00 /mi</text></svg><div className="chart-legend"><span className="legend-hr">Heart rate</span><span className="legend-pace">{runType==='treadmill'?'Corrected pace':'Recorded pace'}</span>{runType==='treadmill'&&<span className="legend-fitness">Stable EF window</span>}</div><p className="viz-note">{runType==='treadmill'?'Distance is reconstructed from the treadmill-corrected workload trace.':'Distance follows the recorded outdoor activity trace.'} This view is intended to show whether cardiovascular response changes as pace changes or remains comparable.</p></div>
}

function buildVirtualLaps(analysis,lapMi,maxHr,restHr){
 if(!analysis?.series?.length||!(lapMi>0))return [];
 const base=analysis.series.filter(r=>r.t>=analysis.startS&&r.t<=analysis.endS&&Number.isFinite(r.distanceMi));
 if(base.length<2)return [];
 const d0=base[0].distanceMi,rel=base.map(r=>({...r,relMi:r.distanceMi-d0}));
 const total=rel.at(-1).relMi,out=[];
 for(let start=0,idx=1;start<total-.02;start+=lapMi,idx++){
   const end=Math.min(total,start+lapMi),pts=rel.filter(r=>r.relMi>=start&&r.relMi<=end);
   if(pts.length<3)continue;
   const first=pts[0],last=pts.at(-1),duration=last.t-first.t,dist=Math.max(.001,last.relMi-first.relMi),mph=dist/(duration/3600);
   const hr=meanFinite(pts.map(r=>r.hr)),cad=meanFinite(pts.map(r=>r.cadenceSpm)),stride=meanFinite(pts.map(r=>r.strideLengthM)),gct=meanFinite(pts.map(r=>r.groundContactTimeMs)),vo=meanFinite(pts.map(r=>r.verticalOscillationMm)),vr=meanFinite(pts.map(r=>r.verticalRatioPct)),bal=meanFinite(pts.map(r=>r.groundContactBalancePct));
   const hrr=maxHr>restHr&&Number.isFinite(hr)?(hr-restHr)/(maxHr-restHr):NaN;
   out.push({idx,start,end,dist,duration,mph,hr,hrr,cad,stride,gct,vo,vr,bal,complete:end-start>=lapMi*.95});
 }
 return out;
}
function VirtualLapAnalysis({analysis,lapMi,setLapMi,maxHr,restHr,runType='treadmill'}){
 const laps=useMemo(()=>buildVirtualLaps(analysis,Number(lapMi),Number(maxHr),Number(restHr)),[analysis,lapMi,maxHr,restHr]);
 if(!analysis)return null;
 const maxHrLap=Math.max(...laps.map(l=>Number.isFinite(l.hr)?l.hr:0),1),minHrLap=Math.min(...laps.map(l=>Number.isFinite(l.hr)?l.hr:maxHrLap),maxHrLap),W=900,H=210,L=44,R=22,T=20,B=40;
 const x=i=>L+(i/Math.max(1,laps.length-1))*(W-L-R),y=v=>H-B-((v-minHrLap)/Math.max(3,maxHrLap-minHrLap))*(H-T-B);
 const path=laps.filter(l=>Number.isFinite(l.hr)).map((l,i)=>(i?'L':'M')+x(i)+' '+y(l.hr)).join(' ');
 return <div className="viz-card virtual-laps"><div className="viz-head"><div><span>VIRTUAL LAP ANALYSIS</span><strong>{runType==='treadmill'?'Standardized treadmill splits':'Standardized distance splits'}</strong></div><label className="inline-setting">Lap length (mi)<input value={lapMi} onChange={e=>setLapMi(e.target.value)} inputMode="decimal"/></label></div>{laps.length?<><svg viewBox={`0 0 ${W} ${H}`}><line className="chart-axis" x1={L} y1={H-B} x2={W-R} y2={H-B}/><path className="hr-line strong-line" d={path}/>{laps.map((l,i)=><g key={l.idx}><circle className="virtual-point" cx={x(i)} cy={y(l.hr)} r="4"/><text className="chart-text tick-label" x={x(i)} y={H-B+17} textAnchor="middle">{l.idx}</text></g>)}</svg><div className="table-wrap"><table className="lap-table"><thead><tr><th>Lap</th><th>Distance</th><th>Time</th><th>Pace</th><th>Avg HR</th><th>HRR</th><th>Cadence</th><th>Stride</th><th>GCT</th><th>Vert. ratio</th></tr></thead><tbody>{laps.map(l=><tr key={l.idx}><td>{l.idx}{!l.complete?'*':''}</td><td>{l.dist.toFixed(2)} mi</td><td>{formatDuration(l.duration)}</td><td>{fmtPaceFromMph(l.mph)}</td><td>{Number.isFinite(l.hr)?Math.round(l.hr)+' bpm':'—'}</td><td>{Number.isFinite(l.hrr)?Math.round(l.hrr*100)+'%':'—'}</td><td>{Number.isFinite(l.cad)?Math.round(l.cad)+' spm':'—'}</td><td>{Number.isFinite(l.stride)?l.stride.toFixed(2)+' m':'—'}</td><td>{Number.isFinite(l.gct)?Math.round(l.gct)+' ms':'—'}</td><td>{Number.isFinite(l.vr)?l.vr.toFixed(1)+'%':'—'}</td></tr>)}</tbody></table></div><p className="viz-note">Virtual laps begin at the detected running segment and use {runType==='treadmill'?'corrected treadmill distance':'recorded outdoor distance'}. An asterisk marks a final partial lap.</p></>:<p className="viz-note">No virtual laps can be formed from the current running segment and lap length.</p>}</div>
}

const DYNAMICS_METRICS=[
 ['cadenceSpm','Cadence','spm',0],['strideLengthM','Stride length','m',2],['groundContactTimeMs','Ground contact time','ms',0],['verticalOscillationMm','Vertical oscillation','mm',1],['verticalRatioPct','Vertical ratio','%',1],['groundContactBalancePct','GCT balance','%',1]
];
function DynamicsProgression({analysis}){
 const available=DYNAMICS_METRICS.filter(([k])=>(analysis?.series||[]).some(r=>Number.isFinite(r[k])));
 const[metric,setMetric]=useState(available[0]?.[0]||'');
 useEffect(()=>{if(available.length&&!available.some(x=>x[0]===metric))setMetric(available[0][0])},[analysis]);
 if(!available.length)return <div className="viz-card"><div className="viz-head"><div><span>RUNNING DYNAMICS</span><strong>No running-dynamics samples detected</strong></div></div><p className="viz-note">Cadence-derived stride length and supported FIT/TCX/GPX running-dynamics fields will appear automatically when present.</p></div>;
 const spec=available.find(x=>x[0]===metric)||available[0],[key,label,unit,digits]=spec;
 const rows=(analysis.series||[]).filter(r=>Number.isFinite(r.distanceMi)&&Number.isFinite(r[key]));const data=rows.length>600?rows.filter((_,i)=>i%Math.ceil(rows.length/600)===0):rows;
 const W=900,H=230,L=58,R=24,T=20,B=42,maxX=Math.max(...data.map(r=>r.distanceMi),.1),vals=data.map(r=>r[key]),minV=Math.min(...vals),maxV=Math.max(...vals),pad=Math.max((maxV-minV)*.12,.5);
 const x=v=>L+(v/maxX)*(W-L-R),y=v=>H-B-((v-(minV-pad))/Math.max(.01,(maxV+pad)-(minV-pad)))*(H-T-B);const path=data.map((r,i)=>(i?'L':'M')+x(r.distanceMi)+' '+y(r[key])).join(' ');
 return <div className="viz-card dynamics-card"><div className="viz-head"><div><span>RUNNING DYNAMICS PROGRESSION</span><strong>{label} across the run</strong></div><select value={key} onChange={e=>setMetric(e.target.value)}>{available.map(([k,l])=><option key={k} value={k}>{l}</option>)}</select></div><svg viewBox={`0 0 ${W} ${H}`}><line className="chart-axis" x1={L} y1={H-B} x2={W-R} y2={H-B}/><path className="dynamics-line" d={path}/><text className="chart-text" x={L} y={H-B+18}>0 mi</text><text className="chart-text" x={W-R} y={H-B+18} textAnchor="end">{maxX.toFixed(2)} mi</text><text className="chart-text" x={L} y={T}>{(maxV+pad).toFixed(digits)} {unit}</text><text className="chart-text" x={L} y={H-B-5}>{(minV-pad).toFixed(digits)} {unit}</text></svg><p className="viz-note">Metrics are shown only when the uploaded activity contains them. Stride length may be derived from corrected speed and running cadence when a native step-length field is unavailable.</p></div>
}

function EarlyLateDynamics({analysis,activity}){
 const rows=(analysis?.series||[]).filter(r=>r.t>=analysis.analysisStartS&&r.t<=analysis.analysisEndS);if(rows.length<20)return null;
 const cut=Math.max(1,Math.floor(rows.length/3)),early=rows.slice(0,cut),late=rows.slice(-cut),all=analysis?.series||[],summary=activity?.runningDynamicsSummary||{};
 const specs=[['speedMph','Pace','pace'],['hr','Heart rate','bpm'],...DYNAMICS_METRICS.map(([k,l,u,d])=>[k,l,u,d])];
 const vals=specs.map(([k,l,u,d=1])=>{const a=meanFinite(early.map(r=>r[k])),b=meanFinite(late.map(r=>r[k]));if(!Number.isFinite(a)||!Number.isFinite(b))return null;let avg=NaN;if(k==='hr'&&Number.isFinite(activity?.avgHr))avg=activity.avgHr;else if(Number.isFinite(summary[k]))avg=summary[k];else avg=meanFinite(all.map(r=>r[k]));const change=u==='pace'&&a>0&&b>0?((a/b)-1)*100:(a!==0?(b/a-1)*100:NaN);return {k,l,u,d,a,b,avg,change,diff:b-a}}).filter(Boolean);
 if(!vals.length)return null;
 const fmtValue=(v,n)=>{if(!Number.isFinite(n))return '—';if(v.u==='pace')return fmtPaceFromMph(n);if(v.k==='groundContactBalancePct')return `${n.toFixed(1)}% L / ${(100-n).toFixed(1)}% R`;return `${n.toFixed(v.d)} ${v.u}`};
 const fmtChange=(v)=>{if(v.k==='groundContactBalancePct'){if(Math.abs(v.diff)<.05)return '0.0 pp';return `${Math.abs(v.diff).toFixed(1)} pp toward ${v.diff>0?'L':'R'}`;}if(v.k==='verticalRatioPct')return `${v.diff>=0?'+':''}${v.diff.toFixed(1)} pp`;return Number.isFinite(v.change)?`${v.change>=0?'+':''}${v.change.toFixed(1)}%`:'—'};
 return <div className="viz-card early-late"><div className="viz-head"><div><span>RUNNING DYNAMICS CHANGE</span><strong>Activity average plus early vs late selected running segment</strong></div><small>first third vs final third</small></div><div className="table-wrap"><table><thead><tr><th>Metric</th><th>Activity avg</th><th>Early</th><th>Late</th><th>Change</th></tr></thead><tbody>{vals.map(v=><tr key={v.k}><td>{v.l}</td><td>{fmtValue(v,v.avg)}</td><td>{fmtValue(v,v.a)}</td><td>{fmtValue(v,v.b)}</td><td>{fmtChange(v)}</td></tr>)}</tbody></table></div><p className="viz-note">For FIT activities, recorded session averages are used for supported running-dynamics metrics when available; Early and Late are Endurance Forge averages from the first and final thirds of the selected running segment. GCT balance is shown as left/right percentages and balance changes are reported in percentage points. This is a descriptive comparison, not a fatigue diagnosis.</p></div>
}

function HrZoneDistribution({analysis,maxHr,restHr}){
 const mx=Number(maxHr),rest=Number(restHr);if(!(mx>rest))return <div className="viz-card"><div className="viz-head"><div><span>HR ZONE DISTRIBUTION</span><strong>HR profile required</strong></div></div><p className="viz-note">Enter known maximum and resting HR to calculate time in heart-rate-reserve zones.</p></div>;
 const rows=(analysis?.series||[]).filter(r=>r.t>=analysis.startS&&r.t<=analysis.endS&&Number.isFinite(r.hr));if(rows.length<2)return null;
 const zones=[['<50%',0,.5],['50–60%',.5,.6],['60–70%',.6,.7],['70–80%',.7,.8],['80–90%',.8,.9],['90%+',.9,9]].map(z=>({...{label:z[0],lo:z[1],hi:z[2]},seconds:0}));
 for(let i=1;i<rows.length;i++){const dt=Math.max(0,Math.min(20,rows[i].t-rows[i-1].t)),hrr=(rows[i-1].hr-rest)/(mx-rest),z=zones.find(q=>hrr>=q.lo&&hrr<q.hi);if(z)z.seconds+=dt;}
 const total=zones.reduce((a,z)=>a+z.seconds,0)||1,max=Math.max(...zones.map(z=>z.seconds),1);
 const intensity=analysis?.intensity;return <div className="viz-card hr-zones"><div className="viz-head"><div><span>HEART-RATE ZONES</span><strong>Time in HR-reserve zones</strong></div><small>detected running segment</small></div>{intensity&&<div className="zone-summary"><span><b>{formatDuration(intensity.above80S)}</b> ≥80% HRR</span><span><b>{formatDuration(intensity.above90S)}</b> ≥90% HRR</span><span><b>{formatDuration(intensity.longest80S)}</b> longest ≥80%</span></div>}<div className="zone-bars">{zones.map(z=><div className="zone-row" key={z.label}><b>{z.label}</b><div><i style={{width:`${z.seconds/max*100}%`}}/></div><span>{formatDuration(z.seconds)} · {Math.round(z.seconds/total*100)}%</span></div>)}</div><p className="viz-note">Zones use heart-rate reserve, not device-specific zone settings.</p></div>
}


function EfficiencyPanel({analysis,maxHr,restHr}){
 const e=analysis?.paceHrEfficiency;
 if(!(Number(maxHr)>Number(restHr)))return <div className="viz-card"><div className="viz-head"><div><span>PACE–HR EFFICIENCY</span><strong>HR profile required</strong></div></div><p className="viz-note">Enter known maximum and resting HR to compare running speed with heart-rate reserve.</p></div>;
 if(!e)return null;
 const decline=-e.changePct;
 return <div className="viz-card efficiency-card"><div className="viz-head"><div><span>PACE–HR EFFICIENCY</span><strong>{e.index.toFixed(2)} mph per 100% HR reserve</strong></div><small>relative efficiency index</small></div><div className="efficiency-pairs"><Metric label="First half" value={e.first.index.toFixed(2)} sub={`${e.first.speed.toFixed(2)} mph · ${Math.round(e.first.hrr*100)}% HRR`}/><Metric label="Second half" value={e.second.index.toFixed(2)} sub={`${e.second.speed.toFixed(2)} mph · ${Math.round(e.second.hrr*100)}% HRR`}/><Metric label="Efficiency change" value={`${e.changePct>=0?'+':''}${e.changePct.toFixed(1)}%`} sub={decline>0?'lower speed per unit HRR late':'relative efficiency maintained/improved'}/></div><p className="viz-note">Index = speed ÷ HR-reserve fraction. The absolute value is not a fitness score; it is most useful for within-run and like-for-like longitudinal comparison. Outdoor terrain and wind are not yet normalized.</p></div>
}

function IntensitySummary({analysis}){
 const i=analysis?.intensity;if(!i)return null;
 return <div className="viz-card intensity-summary"><div className="viz-head"><div><span>INTENSITY SUMMARY</span><strong>Heart-rate-reserve exposure</strong></div><small>selected running segment</small></div><div className="mini-grid"><Metric label="≥80% HRR" value={formatDuration(i.above80S)} sub={`${Math.round(i.above80S/i.totalS*100)}% of analyzed time`}/><Metric label="≥90% HRR" value={formatDuration(i.above90S)} sub={`${Math.round(i.above90S/i.totalS*100)}% of analyzed time`}/><Metric label="Longest ≥80%" value={formatDuration(i.longest80S)} sub="continuous bout"/><Metric label="Peak HRR" value={Number.isFinite(i.peakHrr)?Math.round(i.peakHrr*100)+'%':'—'} sub="from entered HR profile"/></div><p className="viz-note">These values use Endurance Forge HR-reserve calculations and do not reproduce device-specific zone definitions.</p></div>
}

function OutdoorContextMetrics({analysis}){
 const el=analysis?.elevation,p=analysis?.power;
 if(!el&&!p)return null;
 return <div className="viz-card outdoor-context"><div className="viz-head"><div><span>OUTDOOR WORKLOAD CONTEXT</span><strong>Elevation and running power</strong></div><small>when present in the activity file</small></div><div className="mini-grid">{el&&<><Metric label="Elevation gain" value={`${Math.round(el.gainM)} m`} sub="smoothed trace"/><Metric label="Elevation loss" value={`${Math.round(el.lossM)} m`} sub="smoothed trace"/><Metric label="Elevation range" value={`${el.rangeM.toFixed(1)} m`} sub={`${Math.round(el.minM)}–${Math.round(el.maxM)} m`}/></>}{p&&<><Metric label="Average power" value={`${Math.round(p.avgW)} W`} sub="selected running segment"/><Metric label="Power change" value={Number.isFinite(p.changePct)?`${p.changePct>=0?'+':''}${p.changePct.toFixed(1)}%`:'—'} sub="first half → second half"/></>}</div><p className="viz-note">Elevation gain/loss uses a lightly smoothed altitude trace with a small deadband to reduce sample-to-sample noise. Power is reported descriptively and is not yet used to correct outdoor pace or the treadmill EF model.</p></div>
}

function RunInsights({analysis,runType}){
 if(!analysis)return null;
 const items=[];
 const d=analysis.drift,e=analysis.paceHrEfficiency,i=analysis.intensity,el=analysis.elevation,p=analysis.power;
 if(d)items.push({title:d.label||'Aerobic decoupling',text:`Workload-normalized cardiovascular drift was ${d.value>=0?'+':''}${d.value.toFixed(1)}%; average speed changed ${d.speedChange>=0?'+':''}${d.speedChange.toFixed(1)}% between halves.`});
 if(e)items.push({title:'Pace–HR efficiency',text:`Speed per unit of HR reserve ${e.changePct>=0?'improved':'declined'} ${Math.abs(e.changePct).toFixed(1)}% from the first half to the second half.`});
 if(i&&i.above90S>=60)items.push({title:'High-intensity exposure',text:`${formatDuration(i.above90S)} was spent at or above 90% HR reserve, including a longest continuous bout of ${formatDuration(i.longest90S)}.`});
 else if(i&&i.above80S>=120)items.push({title:'Intensity exposure',text:`${formatDuration(i.above80S)} was spent at or above 80% HR reserve.`});
 if(runType==='outdoor'&&el)items.push({title:'Elevation context',text:`The analyzed run accumulated approximately ${Math.round(el.gainM)} m of ascent and ${Math.round(el.lossM)} m of descent from the smoothed recorded altitude trace.`});
 if(p&&Number.isFinite(p.changePct))items.push({title:'Power progression',text:`Average running power changed ${p.changePct>=0?'+':''}${p.changePct.toFixed(1)}% from the first half to the second half.`});
 if(!items.length)return null;
 return <div className="panel insights-panel"><div className="panel-head"><div><span>INSIGHTS</span><h2>What stands out in this run</h2></div><small>rule-based · traceable to metrics</small></div><div className="insights-grid">{items.slice(0,5).map((x,n)=><article key={n}><b>{x.title}</b><p>{x.text}</p></article>)}</div><p className="note">Insights summarize measured relationships; they are not diagnoses or causal conclusions. Use the metric panels below to inspect the underlying values.</p></div>
}

function ActivityChart({analysis,runType='treadmill'}){
 if(!analysis?.series?.length)return null;
 const data=analysis.series.filter(r=>Number.isFinite(r.t)&&(Number.isFinite(r.hr)||Number.isFinite(r.speedMph)));
 if(data.length<5)return null;
 const W=1000,H=230,pad=34,maxT=Math.max(...data.map(r=>r.t),1),hrs=data.map(r=>r.hr).filter(Number.isFinite),sps=data.map(r=>r.speedMph).filter(Number.isFinite);
 const minHr=Math.min(...hrs,60),maxHr=Math.max(...hrs,180),maxSp=Math.max(...sps,6);
 const x=t=>pad+(t/maxT)*(W-pad*2), yHr=v=>H-pad-((v-minHr)/Math.max(1,maxHr-minHr))*(H-pad*2), ySp=v=>H-pad-(v/Math.max(1,maxSp))*(H-pad*2);
 const path=(key,y)=>data.filter(r=>Number.isFinite(r[key])).map((r,i)=>(i?'L':'M')+x(r.t).toFixed(1)+' '+y(r[key]).toFixed(1)).join(' ');
 const sx=x(analysis.analysisStartS),ex=x(analysis.analysisEndS);
 const fs=analysis.fitnessWindow?x(analysis.fitnessWindow.startS):null,fe=analysis.fitnessWindow?x(analysis.fitnessWindow.endS):null;
 return <div className="chart-wrap"><div className="chart-legend"><span className="legend-speed">Speed</span><span className="legend-hr">Heart rate</span><span className="legend-segment">Drift segment</span>{runType==='treadmill'&&<span className="legend-fitness">Fitness window</span>}</div><svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Speed and heart rate over activity time"><rect className="segment-shade" x={sx} y="8" width={Math.max(1,ex-sx)} height={H-16}/>{runType==='treadmill'&&fs!==null&&fe!==null&&<rect className="fitness-shade" x={fs} y="8" width={Math.max(1,fe-fs)} height={H-16}/>}<line className="chart-axis" x1={pad} y1={H-pad} x2={W-pad} y2={H-pad}/><path className="speed-line" d={path('speedMph',ySp)}/><path className="hr-line" d={path('hr',yHr)}/><text className="chart-text" x={pad} y={H-10}>0:00</text><text className="chart-text" textAnchor="end" x={W-pad} y={H-10}>{formatDuration(maxT)}</text></svg></div>
}


function WorkoutTimeline({analysis,runType='treadmill'}){
 if(!analysis?.series?.length)return null;
 const total=Math.max(...analysis.series.map(r=>Number.isFinite(r.t)?r.t:0),analysis.analysisEndS||0,1);
 const pct=v=>Math.max(0,Math.min(100,(v/total)*100));
 const preEnd=pct(analysis.startS||0), runStart=pct(analysis.startS||0), runEnd=pct(analysis.endS||total);
 const analysisStart=pct(analysis.analysisStartS||analysis.startS||0), analysisEnd=pct(analysis.analysisEndS||analysis.endS||total);
 const fs=analysis.fitnessWindow?pct(analysis.fitnessWindow.startS):null, fe=analysis.fitnessWindow?pct(analysis.fitnessWindow.endS):null;
 return <div className="viz-card timeline-card"><div className="viz-head"><div><span>WORKOUT TIMELINE</span><strong>Where Endurance Forge is analyzing</strong></div><small>{formatDuration(total)} total</small></div><div className="timeline" role="img" aria-label="Workout timeline showing warm-up, sustained run, analyzed segment, and fitness window"><div className="timeline-base"><div className="timeline-pre" style={{left:0,width:`${preEnd}%`}}/><div className="timeline-run" style={{left:`${runStart}%`,width:`${Math.max(0,runEnd-runStart)}%`}}/><div className="timeline-analysis" style={{left:`${analysisStart}%`,width:`${Math.max(0,analysisEnd-analysisStart)}%`}}/>{runType==='treadmill'&&fs!==null&&fe!==null&&<div className="timeline-fitness" style={{left:`${fs}%`,width:`${Math.max(0,fe-fs)}%`}}/>}</div><div className="timeline-labels"><span>0:00</span><span>{formatDuration(total)}</span></div></div><div className="viz-legend"><span className="key pre">Warm-up / pre-run</span><span className="key run">Sustained run</span><span className="key analysis">Drift analysis</span>{runType==='treadmill'&&<span className="key fitness">Fitness window</span>}</div></div>
}

function DriftVisual({drift}){
 if(!drift)return null;
 const maxHr=Math.max(drift.firstHr||0,drift.secondHr||0,1), maxSp=Math.max(drift.firstSpeed||0,drift.secondSpeed||0,1);
 const hrw=v=>`${Math.max(3,(v/maxHr)*100)}%`, spw=v=>`${Math.max(3,(v/maxSp)*100)}%`;
 return <div className="viz-card"><div className="viz-head"><div><span>{(drift.label||'HR DRIFT').toUpperCase()}</span><strong>{drift.value>=0?'+':''}{drift.value.toFixed(1)}% workload-normalized</strong></div><small>first half → second half</small></div><div className="drift-pairs"><div className="drift-row"><b>Heart rate</b><div className="paired-bars"><div><i style={{width:hrw(drift.firstHr)}}/><span>{Math.round(drift.firstHr)} bpm</span></div><div><i style={{width:hrw(drift.secondHr)}}/><span>{Math.round(drift.secondHr)} bpm</span></div></div></div><div className="drift-row"><b>Speed</b><div className="paired-bars speed-bars"><div><i style={{width:spw(drift.firstSpeed)}}/><span>{drift.firstSpeed.toFixed(2)} mph</span></div><div><i style={{width:spw(drift.secondSpeed)}}/><span>{drift.secondSpeed.toFixed(2)} mph</span></div></div></div></div><p className="viz-note">Raw HR change {drift.rawHrDrift>=0?'+':''}{drift.rawHrDrift.toFixed(1)}% · speed change {drift.speedChange>=0?'+':''}{drift.speedChange.toFixed(1)}%</p></div>
}

function HrReserveVisual({fit,maxHr,restHr}){
 const mx=Number(maxHr),rest=Number(restHr),avg=fit?.avgHr;
 if(!(mx>rest)&&!Number.isFinite(avg))return null;
 if(!(mx>rest)||!Number.isFinite(avg))return <div className="viz-card reserve-card"><div className="viz-head"><div><span>HEART-RATE RESERVE</span><strong>Profile needed for visualization</strong></div></div><p className="viz-note">Enter known maximum HR and resting HR to place the stable-window response within your HR reserve.</p></div>;
 const p=Math.max(0,Math.min(100,((avg-rest)/(mx-rest))*100));
 return <div className="viz-card reserve-card"><div className="viz-head"><div><span>HEART-RATE RESERVE</span><strong>{Math.round(p)}% HRR in fitness window</strong></div><small>{Math.round(avg)} bpm average</small></div><div className="reserve-track" role="img" aria-label={`Stable-window heart rate is ${Math.round(p)} percent of heart-rate reserve`}><div className="reserve-fill" style={{width:`${p}%`}}/><div className="reserve-marker" style={{left:`${p}%`}}><span>{Math.round(avg)}</span></div></div><div className="reserve-scale"><span>Rest {Math.round(rest)}</span><span>Max {Math.round(mx)}</span></div></div>
}

function CompareBars({runs}){
 if(!runs?.length)return null;
 const usable=runs.filter(r=>Number.isFinite(r.hr)||Number.isFinite(r.drift)); if(!usable.length)return null;
 const maxHr=Math.max(...usable.map(r=>Number.isFinite(r.hr)?r.hr:0),1), maxDrift=Math.max(...usable.map(r=>Number.isFinite(r.drift)?Math.abs(r.drift):0),1);
 return <div className="compare-viz-grid"><div className="viz-card"><div className="viz-head"><div><span>RUN AVG HEART RATE</span><strong>Cardiovascular response by run</strong></div></div><div className="compare-bars">{usable.map((r,i)=><div className="compare-bar-row" key={'hr'+i}><span title={r.name}>{`Run ${i+1}`}</span><div><i className="hr-bar" style={{width:`${Number.isFinite(r.hr)?Math.max(2,r.hr/maxHr*100):0}%`}}/></div><b>{Number.isFinite(r.hr)?Math.round(r.hr)+' bpm':'—'}</b></div>)}</div></div><div className="viz-card"><div className="viz-head"><div><span>HR DRIFT</span><strong>Workload-normalized change by run</strong></div></div><div className="compare-bars">{usable.map((r,i)=><div className="compare-bar-row" key={'drift'+i}><span title={r.name}>{`Run ${i+1}`}</span><div><i className="drift-bar" style={{width:`${Number.isFinite(r.drift)?Math.max(2,Math.abs(r.drift)/maxDrift*100):0}%`}}/></div><b>{Number.isFinite(r.drift)?(r.drift>=0?'+':'')+r.drift.toFixed(1)+'%':'—'}</b></div>)}</div><p className="viz-note">Bar length shows magnitude; the signed value remains the reported result.</p></div></div>
}


const HEAT_METRICS=[
 {key:'fitValue',label:'EF',fmt:v=>v.toFixed(1)},
 {key:'hrrPct',label:'HRR',fmt:v=>Math.round(v)+'%'},
 {key:'drift',label:'HR drift',fmt:v=>(v>=0?'+':'')+v.toFixed(1)+'%'},
 {key:'paceSec',label:'Pace',fmt:v=>`${Math.floor(v/60)}:${String(Math.round(v%60)).padStart(2,'0')}`},
 {key:'cadence',label:'Cadence',fmt:v=>Math.round(v)},
 {key:'gct',label:'GCT',fmt:v=>Math.round(v)},
 {key:'vr',label:'Vert. ratio',fmt:v=>v.toFixed(1)+'%'},
 {key:'efficiencyIndex',label:'Pace/HRR eff.',fmt:v=>v.toFixed(2)},
 {key:'dewPointF',label:'Dew point',fmt:v=>v.toFixed(1)+'°F'}
];
function heatMedian(xs){const a=xs.filter(Number.isFinite).slice().sort((a,b)=>a-b);if(!a.length)return NaN;const m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2}
function heatMad(xs){const m=heatMedian(xs);return Number.isFinite(m)?heatMedian(xs.map(x=>Math.abs(x-m))):NaN}
function heatDeviation(v,values){if(!Number.isFinite(v))return NaN;const m=heatMedian(values),md=heatMad(values);if(!Number.isFinite(m))return NaN;if(md>1e-9)return .6745*(v-m)/md;const sd=Math.sqrt(values.filter(Number.isFinite).reduce((a,x)=>a+(x-m)**2,0)/Math.max(1,values.filter(Number.isFinite).length-1));return sd>1e-9?(v-m)/sd:0}
function heatClass(z){if(!Number.isFinite(z))return 'heat-missing';const a=Math.abs(z);if(a<.5)return 'heat-0';if(z>=1.5)return 'heat-pos-3';if(z>=.9)return 'heat-pos-2';if(z>=.5)return 'heat-pos-1';if(z<=-1.5)return 'heat-neg-3';if(z<=-.9)return 'heat-neg-2';return 'heat-neg-1'}
function runHeatRows(runs){return runs.map(r=>{const rows=(r.analysis?.series||[]).filter(x=>x.t>=r.analysis?.analysisStartS&&x.t<=r.analysis?.analysisEndS);const avg=k=>meanFinite(rows.map(x=>x[k]));const env=r.runType==='treadmill'?environmentSummary(r.environment||{}):{};return {...r,hrrPct:Number.isFinite(r.hrr)?r.hrr*100:NaN,paceSec:r.miles>0&&r.seconds>0?r.seconds/r.miles:NaN,cadence:avg('cadenceSpm'),gct:avg('groundContactTimeMs'),vr:avg('verticalRatioPct'),efficiencyIndex:r.analysis?.paceHrEfficiency?.index,dewPointF:Number.isFinite(env.dewPointC)?fromCelsius(env.dewPointC,'F'):NaN}})}
function sameTypeMetricValues(rows,row,key){return rows.filter(x=>x.runType===row.runType&&Number.isFinite(x[key])).map(x=>x[key])}
function RunPatternHeatMap({runs,filter='all'}){
 const all=runHeatRows(runs.filter(r=>r.included)),rows=filter==='all'?all:all.filter(r=>r.runType===filter);if(rows.length<8)return null;const status=rows.length<15?'Emerging pattern':'Established view';
 const metrics=HEAT_METRICS.filter(m=>rows.filter(r=>Number.isFinite(r[m.key])).length>=Math.max(5,Math.ceil(rows.length*.4)));
 return <div className="viz-card heatmap-card"><div className="viz-head"><div><span>RUN PATTERN HEAT MAP</span><strong>Which runs differ from their comparable baseline?</strong></div><small>{status} · {rows.length} runs</small></div><div className="heat-scroll"><div className="heat-grid" style={{gridTemplateColumns:`104px repeat(${metrics.length}, minmax(82px,1fr))`}}><div className="heat-head">Run</div>{metrics.map(m=><div className="heat-head" key={m.key}>{m.label}</div>)}{rows.map(r=><React.Fragment key={r.id}><div className="heat-run" title={r.name}>Run {r.runIndex+1}<small>{r.runType==='treadmill'?'Treadmill':'Outdoor'}</small></div>{metrics.map(m=>{const vals=sameTypeMetricValues(all,r,m.key),v=r[m.key],z=vals.length>=5?heatDeviation(v,vals):NaN;return <div key={m.key} className={'heat-cell '+heatClass(z)} title={!Number.isFinite(v)?'No data':vals.length<5?`${m.label}: ${m.fmt(v)} · fewer than 5 comparable ${r.runType} runs`:`${m.label}: ${m.fmt(v)} · robust deviation ${z.toFixed(2)} within ${r.runType} runs`}><b>{Number.isFinite(v)?m.fmt(v):'—'}</b><span>{!Number.isFinite(v)?'no data':vals.length<5?'baseline pending':Math.abs(z)<.5?'typical':`${z>0?'+':''}${z.toFixed(1)}σ*`}</span></div>})}</React.Fragment>)}</div></div><div className="heat-legend"><span className="heat-neg-2">Below type baseline</span><span className="heat-0">Near type baseline</span><span className="heat-pos-2">Above type baseline</span></div><p className="viz-note">Treadmill and outdoor runs may appear together, but color is always calculated against the runner's own baseline for the same run type. A type needs at least five usable observations for a metric before deviation color is assigned. This avoids judging an outdoor run against treadmill behavior. Missing metrics stay neutral.</p></div>
}
function pearsonPairs(rows,a,b){const p=rows.map(r=>[r[a],r[b]]).filter(([x,y])=>Number.isFinite(x)&&Number.isFinite(y));if(p.length<6)return {r:NaN,n:p.length};const mx=meanFinite(p.map(x=>x[0])),my=meanFinite(p.map(x=>x[1]));let num=0,dx=0,dy=0;for(const [x,y] of p){num+=(x-mx)*(y-my);dx+=(x-mx)**2;dy+=(y-my)**2}return {r:dx>0&&dy>0?num/Math.sqrt(dx*dy):NaN,n:p.length}}
function corrClass(r){if(!Number.isFinite(r))return 'heat-missing';const a=Math.abs(r);if(a<.2)return 'heat-0';if(r>0)return a>=.7?'heat-pos-3':a>=.4?'heat-pos-2':'heat-pos-1';return a>=.7?'heat-neg-3':a>=.4?'heat-neg-2':'heat-neg-1'}
function normalizedHeatRows(rows,metrics){return rows.map(row=>{const z={...row};for(const m of metrics){const vals=sameTypeMetricValues(rows,row,m.key);z[m.key]=vals.length>=4?heatDeviation(row[m.key],vals):NaN}return z})}
function RelationshipHeatMap({runs,filter='all'}){
 const all=runHeatRows(runs.filter(r=>r.included)),rows=filter==='all'?all:all.filter(r=>r.runType===filter);if(rows.length<8)return null;const metrics=HEAT_METRICS.filter(m=>rows.filter(r=>Number.isFinite(r[m.key])).length>=6).slice(0,8);if(metrics.length<3)return null;const normalized=normalizedHeatRows(rows,metrics);
 return <div className="viz-card heatmap-card relationship-map"><div className="viz-head"><div><span>METRIC RELATIONSHIP HEAT MAP</span><strong>{filter==='all'?'Within-type standardized associations':'Exploratory within-run associations'}</strong></div><small>{rows.length<15?'Emerging pattern':'Exploratory correlation'} · n={rows.length}</small></div><div className="heat-scroll"><div className="corr-grid" style={{gridTemplateColumns:`92px repeat(${metrics.length}, minmax(70px,1fr))`}}><div className="heat-head"></div>{metrics.map(m=><div className="heat-head" key={m.key}>{m.label}</div>)}{metrics.map((a,i)=><React.Fragment key={a.key}><div className="heat-row-label">{a.label}</div>{metrics.map((b,j)=>{if(i===j)return <div key={b.key} className="corr-cell heat-self">1.00</div>;const c=pearsonPairs(normalized,a.key,b.key);return <div key={b.key} className={'corr-cell '+corrClass(c.r)} title={Number.isFinite(c.r)?`${a.label} vs ${b.label}: r=${c.r.toFixed(2)}, n=${c.n}`:`Insufficient paired comparable data (n=${c.n})`}>{Number.isFinite(c.r)?c.r.toFixed(2):'—'}<small>{c.n>=6?`n=${c.n}`:''}</small></div>})}</React.Fragment>)}</div></div><p className="viz-note">Pearson correlations are exploratory and do not establish cause. {filter==='all'?'When treadmill and outdoor runs are mixed, each metric is standardized within run type before association is calculated so different run types are not pooled on raw baselines.':'The selected run type is analyzed on its own baseline.'} Environment applies only to treadmill runs with entered room conditions.</p></div>
}
function MultiRunHeatMaps({runs}){const[filter,setFilter]=useState('all');const included=runs.filter(r=>r.included),counts={all:included.length,treadmill:included.filter(r=>r.runType==='treadmill').length,outdoor:included.filter(r=>r.runType==='outdoor').length};const selected=filter==='all'?counts.all:counts[filter];return <><div className="heat-filter"><div><b>Heat-map run type</b><span>Mixed view uses separate treadmill and outdoor baselines.</span></div><div>{['all','treadmill','outdoor'].map(x=><button key={x} className={filter===x?'active':''} onClick={()=>setFilter(x)}>{x==='all'?'All runs':x==='treadmill'?'Treadmill':'Outdoor'} <small>{counts[x]}</small></button>)}</div></div>{selected>=8?<><RunPatternHeatMap runs={runs} filter={filter}/><RelationshipHeatMap runs={runs} filter={filter}/></>:<div className="heatmap-pending"><b>Pattern heat maps need 8 selected {filter==='all'?'runs':filter+' runs'}.</b><span>With fewer observations, individual run charts are more informative.</span></div>}</>}

function Analyze(){
 const[file,setFile]=useState(null),[activity,setActivity]=useState(null),[error,setError]=useState('');
 const[runType,setRunType]=useState('treadmill'),[typeDetection,setTypeDetection]=useState(null);
 const[distance,setDistance]=useState(''),[time,setTime]=useState(''),[grade,setGrade]=useState(()=>localStorage.getItem('ef-grade')||'0'),[virtualLap,setVirtualLap]=useState(()=>localStorage.getItem('ef-virtual-lap')||'0.25');
 const[maxHr,setMaxHr]=useState(()=>localStorage.getItem('ef-max-hr')||''),[restHr,setRestHr]=useState(()=>localStorage.getItem('ef-rest-hr')||'');
 const[segmentStart,setSegmentStart]=useState(''),[segmentEnd,setSegmentEnd]=useState('');
 const[tempUnit,setTempUnit]=useState('F'),[startTemp,setStartTemp]=useState(''),[startRh,setStartRh]=useState(''),[endTemp,setEndTemp]=useState(''),[endRh,setEndRh]=useState('');
 const load=async(files)=>{const f=files[0];if(!f)return;setError('');setSegmentStart('');setSegmentEnd('');try{const a=await importActivity(f),prefs=readRunPrefs(f),det=inferRunType(a),type=prefs.runType||det.type;setFile(f);setActivity(a);setTypeDetection(det);setRunType(type);setDistance(prefs.distance??(Number.isFinite(safeMiles(a))?safeMiles(a).toFixed(3):''));setTime(prefs.time??(Number.isFinite(safeTime(a))?formatDuration(safeTime(a)):''));setGrade(prefs.grade??localStorage.getItem('ef-grade')??'0');const env=prefs.environment||{};setTempUnit(env.tempUnit||'F');setStartTemp(env.startTemp??'');setStartRh(env.startRh??'');setEndTemp(env.endTemp??'');setEndRh(env.endRh??'')}catch(e){setError(e.message);setActivity(null)}};
 useEffect(()=>{if(file)writeRunPrefs(file,{runType,distance,time,grade,environment:{tempUnit,startTemp,startRh,endTemp,endRh}})},[file,runType,distance,time,grade,tempUnit,startTemp,startRh,endTemp,endRh]);
 const isTreadmill=runType==='treadmill', recordedMiles=safeMiles(activity), recordedSeconds=safeTime(activity);
 const seconds=useMemo(()=>isTreadmill?parseClock(time):recordedSeconds,[isTreadmill,time,recordedSeconds]), miles=isTreadmill?Number(distance):recordedMiles, targetM=miles>0?miles*1609.344:NaN;
 const analysis=useMemo(()=>activity?analyzeTreadmillActivity(activity,{targetDistanceM:targetM,targetTimerS:seconds,gradePct:isTreadmill?(Number(grade)||0):0,maxHr:Number(maxHr),restHr:Number(restHr),manualStartS:parseClock(segmentStart),manualEndS:parseClock(segmentEnd)}):null,[activity,targetM,seconds,grade,maxHr,restHr,segmentStart,segmentEnd,isTreadmill]);
 const pace=miles>0&&seconds>0?pacePerMile(miles,seconds):null,mph=miles>0&&seconds>0?miles/(seconds/3600):null,oxy=isTreadmill&&mph?oxygenCostLevelRun(mph,Number(grade)||0):null;
 const runMiles=analysis?.avgSpeedMph>0?analysis.avgSpeedMph*(analysis.segmentDurationS/3600):NaN, preMiles=analysis?.preSegmentAvgSpeedMph>0?analysis.preSegmentAvgSpeedMph*(analysis.preSegmentDurationS/3600):NaN;
 const fit=isTreadmill?analysis?.fitness:null, drift=analysis?.drift, environment=isTreadmill?environmentSummary({tempUnit,startTemp,startRh,endTemp,endRh}):{available:false};
 const elevs=(activity?.records||[]).map(r=>r.elevationM).filter(Number.isFinite), elevationRange=elevs.length?Math.max(...elevs)-Math.min(...elevs):NaN;
 const avgPower=meanFinite((activity?.records||[]).map(r=>r.powerW));
 const saveProfile=(setter,key)=>(e)=>{setter(e.target.value);localStorage.setItem(key,e.target.value)};
 const download=()=>{try{const out=correctActivityFile(activity,targetM,seconds);const blob=new Blob([out.bytes],{type:'application/octet-stream'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file.name.replace(/\.fit$/i,'')+'_EnduranceForge_Corrected.fit';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){setError(e.message)}};
 return <section className="workspace"><div className="page-title"><div><div className="eyebrow">SINGLE RUN ANALYSIS</div><h1>Run Analyzer</h1><p>Analyze outdoor and treadmill activities with a workflow that adapts to the run. GPS-tracked activities use recorded outdoor data; treadmill runs unlock corrected workload inputs and the EF aerobic-fitness model.</p></div><div className="pill">PROCESSED LOCALLY IN YOUR BROWSER</div></div>
 {!activity?<DropZone onFiles={load}/>:<><div className="filebar"><div><b>{file.name}</b><span><em className={'format-tag '+activity.format.toLowerCase()}>{activity.format}</em>{activity.records.length} samples · {activity.laps.length} laps</span></div><button className="link" onClick={()=>{setActivity(null);setFile(null);setError('')}}>Choose another file</button></div>
 <div className="panel run-detection-panel"><div className="panel-head"><div><span>01</span><h2>Activity type</h2></div><small>{typeDetection?.confidence?`${typeDetection.confidence} confidence auto-detection`:'Automatic detection'}</small></div><div className="run-detection-grid"><div><span className={'run-type-tag '+runType}>{runType==='outdoor'?'Outdoor run':'Treadmill / indoor run'}</span><p className="note">{typeDetection?.reason||'Activity type inferred from available activity data.'} You can override the classification at any time.</p></div><label>Analyze as<select value={runType} onChange={e=>setRunType(e.target.value)}><option value="outdoor">Outdoor run</option><option value="treadmill">Treadmill / indoor run</option></select></label></div></div>
 <div className="two-col">{isTreadmill?<div className="panel"><div className="panel-head"><div><span>02</span><h2>Treadmill inputs</h2></div><small>Authoritative workload inputs</small></div><div className="form-grid"><label>Distance (miles)<input value={distance} onChange={e=>setDistance(e.target.value)} inputMode="decimal"/></label><label>Time<input value={time} onChange={e=>setTime(e.target.value)}/></label><label>Incline / grade (%)<input value={grade} onChange={e=>{setGrade(e.target.value);localStorage.setItem('ef-grade',e.target.value)}} inputMode="decimal"/></label></div><GradeConfirmation grade={grade}/><p className="note">These values calibrate the treadmill workload trace. Grade is remembered from your previous analysis but is never inferred from the watch; confirm it for each treadmill run.</p></div>:<div className="panel"><div className="panel-head"><div><span>02</span><h2>Outdoor activity</h2></div><small>Recorded GPS workload</small></div><div className="mini-grid"><Metric label="GPS track" value={activity.capabilities.gpsTrack?'Detected':'Unavailable'}/><Metric label="Elevation" value={activity.capabilities.elevation?'Detected':'Unavailable'} sub={Number.isFinite(elevationRange)?`${elevationRange.toFixed(1)} m observed range`:''}/><Metric label="Cadence" value={activity.capabilities.cadenceSamples?'Detected':'Unavailable'}/><Metric label="Power" value={activity.capabilities.powerSamples?'Detected':'Unavailable'} sub={Number.isFinite(avgPower)?`${Math.round(avgPower)} W sample average`:''}/></div><p className="note">Outdoor analysis uses the recorded distance, time, GPS, elevation and other available sensor data. Treadmill correction and treadmill-only EF calculations are disabled.</p></div>}
 <div className="panel"><div className="panel-head"><div><span>03</span><h2>Recorded activity</h2></div><small>{activity.sourceLabel}</small></div><div className="mini-grid"><Metric label="Recorded distance" value={Number.isFinite(recordedMiles)?recordedMiles.toFixed(2)+' mi':'—'}/><Metric label="Recorded time" value={Number.isFinite(recordedSeconds)?formatDuration(recordedSeconds):'—'}/><Metric label="Average HR" value={Number.isFinite(activity.avgHr)?Math.round(activity.avgHr)+' bpm':'—'}/><Metric label="Activity max HR" value={Number.isFinite(activity.maxHr)?Math.round(activity.maxHr)+' bpm':'—'} sub="not assumed to be HRmax"/></div></div></div>
 {isTreadmill&&<EnvironmentPanel tempUnit={tempUnit} setTempUnit={setTempUnit} startTemp={startTemp} setStartTemp={setStartTemp} startRh={startRh} setStartRh={setStartRh} endTemp={endTemp} setEndTemp={setEndTemp} endRh={endRh} setEndRh={setEndRh}/>}
 <div className="panel capability-panel"><div className="panel-head"><div><span>04</span><h2>Detected data capabilities</h2></div><small>Metrics adapt to the file</small></div><Capabilities activity={activity}/></div>
 <div className="panel segment-panel"><div className="panel-head"><div><span>05</span><h2>Workout structure</h2></div><small>{analysis?.auto?.detected?'Sustained running detected':'Automatic segmentation limited'}</small></div>
 {analysis&&<><div className="structure-grid"><Metric label="Pre-run / warm-up" value={analysis.preSegmentDurationS>30?formatDuration(analysis.preSegmentDurationS):'None detected'} sub={Number.isFinite(preMiles)?`≈ ${preMiles.toFixed(2)} mi from speed trace`:''}/><Metric label="Detected run" value={formatDuration(analysis.segmentDurationS)} sub={Number.isFinite(runMiles)?`≈ ${runMiles.toFixed(2)} mi · ${fmtMph(analysis.avgSpeedMph)}`:fmtMph(analysis.avgSpeedMph)}/><Metric label="Analysis starts" value={formatDuration(analysis.analysisStartS)} sub={analysis.analysisStartS>analysis.startS?'HR-settling transition trimmed':'No automatic trim'}/><Metric label="Run avg HR" value={Number.isFinite(analysis.avgHr)?Math.round(analysis.avgHr)+' bpm':'—'} sub={isTreadmill&&analysis.fitnessWindow?`Stable EF window ${formatDuration(analysis.fitnessWindow.startS)}–${formatDuration(analysis.fitnessWindow.endS)}`:'selected running segment'}/></div><ActivityChart analysis={analysis} runType={runType}/><WorkoutTimeline analysis={analysis} runType={runType}/><div className="segment-controls"><div><strong>Override analyzed segment</strong><span>Leave blank to use automatic detection.</span></div><label>Start<input value={segmentStart} onChange={e=>setSegmentStart(e.target.value)} placeholder={formatDuration(analysis.analysisStartS)}/></label><label>End<input value={segmentEnd} onChange={e=>setSegmentEnd(e.target.value)} placeholder={formatDuration(analysis.analysisEndS)}/></label><button className="secondary compact" onClick={()=>{setSegmentStart('');setSegmentEnd('')}}>Use automatic</button></div></>}
 </div>
 <div className="panel profile-panel"><div className="panel-head"><div><span>06</span><h2>Physiological inputs</h2></div><small>Stored only in this browser</small></div><div className="profile-row"><label>Known maximum HR (bpm)<input value={maxHr} onChange={saveProfile(setMaxHr,'ef-max-hr')} inputMode="numeric" placeholder="e.g. 185"/></label><label>Resting HR (bpm)<input value={restHr} onChange={saveProfile(setRestHr,'ef-rest-hr')} inputMode="numeric" placeholder="e.g. 55"/></label><p>These are optional for general analysis but required for heart-rate-reserve analysis and the treadmill-specific EF Aerobic Fitness Estimate. The highest HR in this workout is <b>not</b> substituted for known HRmax.</p></div></div>
 {isTreadmill?<><div className="metric-grid five"><Metric label="Corrected pace" value={pace||'—'} sub="whole activity"/><Metric label="Corrected speed" value={mph?mph.toFixed(2)+' mph':'—'} sub="whole activity"/><Metric label="Running O₂ cost" value={fit?.workloadVo2?fit.workloadVo2.toFixed(1):(analysis?.avgSpeedMph?oxygenCostLevelRun(analysis.avgSpeedMph,Number(grade)||0).toFixed(1):oxy?.toFixed(1)||'—')} sub="mL/kg/min · workload"/><Metric label={drift?.label||'HR drift'} value={drift?(drift.value>=0?'+':'')+drift.value.toFixed(1)+'%':'—'} sub={drift?'running segment · workload-normalized':'needs comparable HR + speed'}/><Metric label="EF Aerobic Fitness Estimate" value={fit&&Number.isFinite(fit.value)?fit.value.toFixed(1):'—'} sub={fit&&Number.isFinite(fit.value)?`mL/kg/min · VO₂max-equivalent · ${fit.confidence} inference`:(fit?.reason||'requires suitable segment + HR profile')} tone={confidenceClass(fit?.confidence)}/></div><div className="metric-help"><span><b>Running O₂ Cost</b> describes the oxygen demand of the treadmill workload. <b>EF Aerobic Fitness Estimate</b> is the VO₂max-equivalent capacity inferred from workload + heart-rate response.</span></div></>:<><div className="metric-grid five"><Metric label="Recorded pace" value={pace||'—'} sub="whole activity"/><Metric label="Average speed" value={mph?mph.toFixed(2)+' mph':'—'} sub="whole activity"/><Metric label="Run avg HR" value={Number.isFinite(analysis?.avgHr)?Math.round(analysis.avgHr)+' bpm':'—'} sub="selected running segment"/><Metric label={drift?.label||'HR drift'} value={drift?(drift.value>=0?'+':'')+drift.value.toFixed(1)+'%':'—'} sub={drift?'selected running segment':'needs comparable HR + speed'}/><Metric label="Elevation data" value={activity.capabilities.elevation?'Available':'—'} sub={Number.isFinite(elevationRange)?`${elevationRange.toFixed(1)} m observed range`:'record-level altitude'}/></div><div className="metric-help"><span>Outdoor runs use recorded pace, GPS, elevation, heart rate, dynamics and available sensor data. The treadmill EF Aerobic Fitness Estimate is intentionally not calculated for outdoor activities.</span></div></>}
 <div className="insight-viz-grid"><DriftVisual drift={drift}/>{isTreadmill&&<HrReserveVisual fit={fit} maxHr={maxHr} restHr={restHr}/>}</div>
 <RunInsights analysis={analysis} runType={runType}/><div className="analysis-viz-grid"><EfficiencyPanel analysis={analysis} maxHr={maxHr} restHr={restHr}/><IntensitySummary analysis={analysis}/></div>{!isTreadmill&&<OutdoorContextMetrics analysis={analysis}/>}<PaceHrProgression analysis={analysis} runType={runType}/><VirtualLapAnalysis analysis={analysis} lapMi={virtualLap} setLapMi={v=>{setVirtualLap(v);localStorage.setItem('ef-virtual-lap',v)}} maxHr={maxHr} restHr={restHr} runType={runType}/><div className="analysis-viz-grid"><DynamicsProgression analysis={analysis}/><HrZoneDistribution analysis={analysis} maxHr={maxHr} restHr={restHr}/></div><EarlyLateDynamics analysis={analysis} activity={activity}/>
 {isTreadmill?<div className="result-panel"><div><div className="eyebrow">ENDURANCE FORGE AEROBIC ANALYSIS</div><h2>{fit&&Number.isFinite(fit.value)?`EF Aerobic Fitness Estimate: ${fit.value.toFixed(1)} mL/kg/min`:'Insufficient data for a reliable aerobic fitness estimate.'}</h2><div className="equivalent-label">TREADMILL-DERIVED VO₂MAX-EQUIVALENT ESTIMATE</div><p>{fit?.reason||'The current activity does not support the estimate yet.'} {drift?`The drift calculation compares workload-normalized HR within the selected running segment; average speed changed ${drift.speedChange>=0?'+':''}${drift.speedChange.toFixed(1)}% between halves.`:''}</p>{environment.available&&<div className="environment-context"><b>Environmental context:</b> {environment.context} {Number.isFinite(environment.rhChange)?`Humidity changed ${environment.rhChange>=0?'+':''}${environment.rhChange.toFixed(0)} percentage points during the session. `:''}These conditions do not alter the EF estimate.</div>}<div className="disclaimer">Comparable to VO₂max in concept and units, but not directly interchangeable with a laboratory or device-manufacturer value. It is not Garmin VO₂max and not a laboratory VO₂max measurement.</div></div><div className={'status-card '+confidenceClass(fit?.confidence)}><span>Inference confidence</span><strong>{fit?.confidence||'Unavailable'}</strong><small>{fit&&Number.isFinite(fit.hrr)?`${Math.round(fit.hrr*100)}% HR reserve · ${formatDuration(fit.durationS)} stable window`:fit?.reason}</small><span className="quality-line">Data quality: <b>{analysis?.dataQuality?.level||'Unavailable'}</b></span></div></div>:<div className="result-panel"><div><div className="eyebrow">OUTDOOR RUN ANALYSIS</div><h2>Outdoor activity analyzed from recorded run data.</h2><p>Endurance Forge detected an outdoor workflow and retained the activity's recorded distance, time, GPS, elevation and available sensor metrics. Treadmill-only workload and EF aerobic-fitness calculations were intentionally omitted.</p></div><div className="status-card"><span>Activity classification</span><strong>Outdoor</strong><small>{typeDetection?.reason}</small><span className="quality-line">Data quality: <b>{analysis?.dataQuality?.level||'Unavailable'}</b></span></div></div>}
 {isTreadmill&&<div className="actions"><button className="primary" disabled={activity.format!=='FIT'||!miles||!seconds} onClick={download}>{activity.format==='FIT'?'Download corrected FIT':`Corrected ${activity.format} export — later`}</button><span>Your original file is never modified.</span></div>}</>}{error&&<div className="error">{error}</div>}</section>
}

function MultiRunPlot({combined}){
 if(!combined?.available||!combined.points?.length)return null;
 const pts=combined.points, W=760,H=330,padL=64,padR=22,padT=25,padB=52;
 const xs=pts.map(p=>p.hrr*100),ys=pts.map(p=>p.workloadVo2);
 const minX=Math.max(30,Math.floor((Math.min(...xs)-5)/5)*5),maxX=Math.min(95,Math.ceil((Math.max(...xs)+5)/5)*5);
 const lineY=xPct=>3.5+(combined.value-3.5)*(xPct/100);
 const lineYs=[lineY(minX),lineY(maxX)],minY=Math.max(10,Math.floor((Math.min(...ys,...lineYs)-2)/5)*5),maxY=Math.ceil((Math.max(...ys,...lineYs)+2)/5)*5;
 const x=v=>padL+((v-minX)/Math.max(1,maxX-minX))*(W-padL-padR),y=v=>H-padB-((v-minY)/Math.max(1,maxY-minY))*(H-padT-padB);
 const xTicks=[];for(let v=Math.ceil(minX/5)*5;v<=maxX;v+=5)xTicks.push(v);
 const yTicks=[];for(let v=Math.ceil(minY/5)*5;v<=maxY;v+=5)yTicks.push(v);
 return <div className="viz-card multi-plot"><div className="viz-head"><div><span>WORKLOAD–HEART-RATE RELATIONSHIP</span><strong>Model-eligible runs vs combined EF model</strong></div><small>{combined.eligibleCount} runs · {combined.distinctWorkloads} workload levels</small></div><svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Workload oxygen cost versus heart-rate reserve for model-eligible treadmill runs">{xTicks.map(v=><g key={'x'+v}><line className="chart-grid" x1={x(v)} y1={padT} x2={x(v)} y2={H-padB}/><text className="chart-text tick-label" x={x(v)} y={H-padB+18} textAnchor="middle">{v}%</text></g>)}{yTicks.map(v=><g key={'y'+v}><line className="chart-grid" x1={padL} y1={y(v)} x2={W-padR} y2={y(v)}/><text className="chart-text tick-label" x={padL-9} y={y(v)+4} textAnchor="end">{v}</text></g>)}<line className="chart-axis" x1={padL} y1={H-padB} x2={W-padR} y2={H-padB}/><line className="chart-axis" x1={padL} y1={padT} x2={padL} y2={H-padB}/><line className="model-line" x1={x(minX)} y1={y(lineY(minX))} x2={x(maxX)} y2={y(lineY(maxX))}/>{pts.map((p,i)=><g key={i}><circle className={'run-point '+(p.evidence?.tier==='supporting'?'supporting':'primary')} cx={x(p.hrr*100)} cy={y(p.workloadVo2)} r="6"/><text className="chart-text point-label" x={x(p.hrr*100)+8} y={y(p.workloadVo2)-8}>{`Run ${p.runIndex+1}`}</text></g>)}<text className="chart-text" x={(padL+W-padR)/2} y={H-9} textAnchor="middle">Heart-rate reserve (%)</text><text className="chart-text axis-label-y" transform={`translate(16 ${(padT+H-padB)/2}) rotate(-90)`} textAnchor="middle">Workload O₂ (mL/kg/min)</text><text className="model-label" x={W-padR} y={Math.max(padT+12,y(lineY(maxX))-8)} textAnchor="end">EF {combined.value.toFixed(1)}</text></svg><p className="viz-note">Filled points are Primary evidence; outlined points are Supporting evidence. Axes show the actual HR-reserve and workload range. The line is the robust combined relationship, not a laboratory VO₂ measurement.</p></div>
}

function EvidenceBadge({assessment}){const a=assessment||{status:'Excluded',tier:'excluded',reasons:['No assessment available.']};return <div className="evidence-cell"><span className={'evidence-badge '+a.tier}>{a.status}</span><span className="why-text">{a.reasons.join(' ')}</span></div>}

function Compare(){
 const[runs,setRuns]=useState([]),[error,setError]=useState(''),[envOpen,setEnvOpen]=useState(false);
 const[maxHr,setMaxHr]=useState(()=>localStorage.getItem('ef-max-hr')||''),[restHr,setRestHr]=useState(()=>localStorage.getItem('ef-rest-hr')||'');
 const saveProfile=(setter,key)=>(e)=>{setter(e.target.value);localStorage.setItem(key,e.target.value)};
 const load=async(files)=>{setError('');const out=[];for(const f of files){try{const a=await importActivity(f),m=safeMiles(a),t=safeTime(a),prefs=readRunPrefs(f),det=inferRunType(a),autoType=det.type,hasSavedType=!!prefs.runType;out.push({id:`${f.name}-${f.size}-${f.lastModified}`,name:f.name,format:a.format,activity:a,sourceFile:f,runType:prefs.runType||autoType,detectedType:autoType,detectionConfidence:det.confidence||'Unknown',detectionReason:det.reason||'',runTypeOverride:hasSavedType&&prefs.runType!==autoType,distance:prefs.distance??(Number.isFinite(m)?m.toFixed(3):''),time:prefs.time??(Number.isFinite(t)?formatDuration(t):''),grade:prefs.grade??localStorage.getItem('ef-grade')??'0',environment:prefs.environment||{},included:true})}catch(e){setError(prev=>prev+(prev?'\n':'')+f.name+': '+e.message)}}setRuns(current=>{const existing=new Set(current.map(r=>r.id)),added=out.filter(r=>!existing.has(r.id));return [...current,...added]})};
 const persistRun=(next)=>writeRunPrefs(next.sourceFile,{runType:next.runType,distance:next.distance,time:next.time,grade:next.grade,environment:next.environment||{}});
 const patchRun=(id,field,value)=>setRuns(rs=>rs.map(r=>{if(r.id!==id)return r;const next={...r,[field]:value};if(field==='runType'){next.runTypeOverride=value!==r.detectedType;if(value==='outdoor')next.environment={};}if(['distance','time','grade','runType'].includes(field)){persistRun(next);if(field==='grade')localStorage.setItem('ef-grade',value)}return next;}));
 const patchEnv=(id,field,value)=>setRuns(rs=>rs.map(r=>{if(r.id!==id||r.runType!=='treadmill')return r;const next={...r,environment:{...(r.environment||{}),[field]:value}};persistRun(next);return next;}));
 const analyzed=useMemo(()=>runs.map((r,runIndex)=>{const recordedMiles=safeMiles(r.activity),recordedSeconds=safeTime(r.activity),isTreadmill=r.runType==='treadmill',miles=isTreadmill?Number(r.distance):recordedMiles,seconds=isTreadmill?parseClock(r.time):recordedSeconds,gradePct=isTreadmill?(Number(r.grade)||0):0,targetM=miles>0?miles*1609.344:NaN;const an=analyzeTreadmillActivity(r.activity,{targetDistanceM:targetM,targetTimerS:seconds,gradePct,maxHr:Number(maxHr),restHr:Number(restHr)}),fit=isTreadmill?an?.fitness:null,hrr=Number.isFinite(an?.fitness?.hrr)?an.fitness.hrr:(Number(maxHr)>Number(restHr)&&Number.isFinite(an?.avgHr)?(an.avgHr-Number(restHr))/(Number(maxHr)-Number(restHr)):NaN);return {...r,runIndex,miles,seconds,pace:miles>0&&seconds>0?pacePerMile(miles,seconds):'—',hr:an?.avgHr,drift:an?.drift?.value,efficiencyIndex:an?.paceHrEfficiency?.index,efficiencyChange:an?.paceHrEfficiency?.changePct,highIntensityS:an?.intensity?.above80S,segment:an?.segmentDurationS,fitValue:fit?.value,hrr,workloadVo2:fit?.workloadVo2,singleConfidence:isTreadmill?(fit?.confidence||'Unavailable'):'Not applicable',dataQuality:an?.dataQuality?.level,analysis:an}}),[runs,maxHr,restHr]);
 const treadmillModelRuns=useMemo(()=>analyzed.map(r=>({...r,included:r.included&&r.runType==='treadmill'})),[analyzed]);
 const combined=useMemo(()=>combineAerobicFitness(treadmillModelRuns),[treadmillModelRuns]);
 const assessmentById=useMemo(()=>new Map((combined.assessments||[]).map(a=>[a.id,a])),[combined]);
 const selectedTreadmill=analyzed.filter(r=>r.included&&r.runType==='treadmill').length,selectedOutdoor=analyzed.filter(r=>r.included&&r.runType==='outdoor').length;
 return <section className="workspace"><div className="page-title"><div><div className="eyebrow">MULTI-RUN ANALYSIS</div><h1>Analyze multiple runs</h1><p>Load treadmill runs, outdoor runs, or any combination of both. Explore patterns in physiological response, performance, and running dynamics across multiple activities. Endurance Forge keeps treadmill-specific calculations and unlike conditions appropriately separated so the analysis remains meaningful.</p></div><div className="pill">MULTI-RUN ANALYSIS</div></div>
 <DropZone multiple onFiles={load} title={runs.length?"Add more FIT, TCX, or GPX files":"Drop several FIT, TCX, or GPX files here"}/>
 {runs.length>0&&<><div className="panel profile-panel"><div className="panel-head"><div><span>01</span><h2>Shared physiological profile</h2></div><small>Used for every selected run</small></div><div className="profile-row"><label>Known maximum HR<input value={maxHr} onChange={saveProfile(setMaxHr,'ef-max-hr')} inputMode="numeric" placeholder="e.g. 179"/></label><label>Resting HR<input value={restHr} onChange={saveProfile(setRestHr,'ef-rest-hr')} inputMode="numeric" placeholder="e.g. 47"/></label><p>Use the same known maximum and resting HR across the comparison. Outdoor runs can contribute HR, drift, pace, and running-dynamics context, but they are not used in the treadmill-derived EF fitness model.</p></div></div>
 <div className="panel table-panel multi-input-panel"><div className="panel-head"><div><span>02</span><h2>Run type and workload inputs</h2></div><small>{selectedTreadmill} treadmill · {selectedOutdoor} outdoor selected</small></div><p className="note">Each activity is automatically classified as Outdoor or Treadmill/Indoor before analysis. The Run Type column shows the current classification and whether it is automatic or a manual override. Treadmill distance, time, and grade can be corrected to the machine display. Outdoor runs retain their recorded distance/time and are excluded only from the EF treadmill model—not from general comparison or heat maps.</p><div className="table-wrap"><table className="multi-input-table evidence-table"><thead><tr><th>Use</th><th>File</th><th>Run Type</th><th>Distance mi</th><th>Time</th><th>Grade %</th><th>Avg HR</th><th>HRR</th><th>O₂ workload</th><th>Single-run EF</th><th>Quality</th><th>EF model / why</th></tr></thead><tbody>{analyzed.map(r=><tr key={r.id}><td><input type="checkbox" checked={r.included} onChange={e=>patchRun(r.id,'included',e.target.checked)} aria-label={`Include ${r.name}`}/></td><td><b>{r.name}</b><br/><em className={'format-tag '+r.format.toLowerCase()}>{r.format}</em></td><td className="run-type-cell"><span className={'run-type-tag '+r.runType}>{r.runType==='treadmill'?'Treadmill':'Outdoor'}</span><select className="table-input run-type-input" value={r.runType} onChange={e=>patchRun(r.id,'runType',e.target.value)} aria-label={`Run type for ${r.name}`}><option value="treadmill">Treadmill</option><option value="outdoor">Outdoor</option></select><small className={'cell-sub detection-state '+(r.runTypeOverride?'manual':'auto')}>{r.runTypeOverride?'Manual override':`Auto · ${r.detectionConfidence}`}</small></td><td>{r.runType==='treadmill'?<input className="table-input" value={r.distance} onChange={e=>patchRun(r.id,'distance',e.target.value)} inputMode="decimal"/>:<><b>{Number.isFinite(r.miles)?r.miles.toFixed(3):'—'}</b><small className="cell-sub">recorded</small></>}</td><td>{r.runType==='treadmill'?<input className="table-input time-input" value={r.time} onChange={e=>patchRun(r.id,'time',e.target.value)}/>:<><b>{Number.isFinite(r.seconds)?formatDuration(r.seconds):'—'}</b><small className="cell-sub">recorded</small></>}</td><td>{r.runType==='treadmill'?<input className="table-input grade-input" value={r.grade} onChange={e=>patchRun(r.id,'grade',e.target.value)} inputMode="decimal"/>:'—'}</td><td>{Number.isFinite(r.hr)?Math.round(r.hr)+' bpm':'—'}</td><td>{Number.isFinite(r.hrr)?Math.round(r.hrr*100)+'%':'—'}</td><td>{r.runType==='treadmill'&&Number.isFinite(r.workloadVo2)?r.workloadVo2.toFixed(1):'—'}</td><td>{r.runType==='treadmill'&&Number.isFinite(r.fitValue)?r.fitValue.toFixed(1):'—'}<small className="cell-sub">{r.runType==='treadmill'?r.singleConfidence:'outdoor'}</small></td><td>{r.dataQuality||'—'}</td><td>{r.runType==='treadmill'?<EvidenceBadge assessment={assessmentById.get(r.id)}/>:<div className="evidence-cell"><span className="evidence-badge outdoor">Outdoor</span><span className="why-text">Included in mixed-run analytics; not used in the treadmill EF model.</span></div>}</td></tr>)}</tbody></table></div></div>
 {analyzed.some(r=>r.runType==='treadmill')&&<div className={'panel table-panel environment-compare-panel '+(envOpen?'open':'collapsed')}><button type="button" className="collapse-head" onClick={()=>setEnvOpen(v=>!v)} aria-expanded={envOpen}><div className="panel-head collapse-panel-head"><div><span>ENV</span><h2>Indoor environment by treadmill run <small className="optional-label">optional</small></h2></div><div className="collapse-summary"><small>Context only · does not alter EF</small><b>{envOpen?'−':'+'}</b></div></div></button>{envOpen&&<div className="collapse-body"><p className="note">Add room conditions for treadmill runs when available. Outdoor runs are intentionally omitted from this panel because two-point room temperature/humidity context is designed for controlled indoor sessions.</p><div className="table-wrap"><table className="environment-table"><thead><tr><th>Run</th><th>Unit</th><th>Start temp</th><th>Start RH %</th><th>End temp</th><th>End RH %</th><th>Avg dew point</th></tr></thead><tbody>{analyzed.filter(r=>r.runType==='treadmill').map(r=>{const e=r.environment||{},es=environmentSummary(e);return <tr key={r.id}><td>Run {r.runIndex+1}</td><td><select className="table-input env-unit-input" value={e.tempUnit||'F'} onChange={x=>patchEnv(r.id,'tempUnit',x.target.value)}><option value="F">°F</option><option value="C">°C</option></select></td><td><input className="table-input" value={e.startTemp??''} onChange={x=>patchEnv(r.id,'startTemp',x.target.value)} inputMode="decimal"/></td><td><input className="table-input" value={e.startRh??''} onChange={x=>patchEnv(r.id,'startRh',x.target.value)} inputMode="decimal"/></td><td><input className="table-input" value={e.endTemp??''} onChange={x=>patchEnv(r.id,'endTemp',x.target.value)} inputMode="decimal"/></td><td><input className="table-input" value={e.endRh??''} onChange={x=>patchEnv(r.id,'endRh',x.target.value)} inputMode="decimal"/></td><td>{Number.isFinite(es.dewPointC)?fmtTempC(es.dewPointC,e.tempUnit||'F'):'—'}</td></tr>})}</tbody></table></div></div>}</div>}
 <div className={'multi-result '+confidenceClass(combined.confidence)}><div><div className="eyebrow">COMBINED EF AEROBIC FITNESS ESTIMATE</div><h2>{combined.available?`${combined.value.toFixed(1)} mL/kg/min`:'Not enough qualifying treadmill runs yet'}</h2><div className="equivalent-label">ROBUST MULTI-RUN · TREADMILL-DERIVED VO₂MAX-EQUIVALENT</div><p>{combined.reason} Outdoor runs remain visible in the mixed-run analysis but do not influence this estimate.</p></div><div className="multi-result-stats"><Metric label="Inference confidence" value={combined.confidence}/><Metric label="Treadmill evidence" value={`${combined.primaryCount||0} P · ${combined.supportingCount||0} S`} sub={`${combined.excludedCount||0} excluded`}/><Metric label="Workload span" value={combined.available?combined.workloadRange.toFixed(1):'—'} sub="mL/kg/min"/><Metric label="Run agreement" value={combined.available?`MAD ${combined.spreadMad.toFixed(1)}`:'—'} sub="treadmill single-run EF spread"/></div></div>
 <div className="evidence-summary"><div><b>Primary</b><span>Strong treadmill-model evidence: adequate stable-window duration with no major inference limitation.</span></div><div><b>Supporting</b><span>Usable treadmill observation, automatically down-weighted for a stated evidence limitation.</span></div><div><b>Outdoor</b><span>Included in mixed-run trends, pace/HR/running-dynamics comparison, and heat maps; never fed into the treadmill EF model.</span></div></div><div className="performance-neutral-note"><b>Run type separation is methodological, not a performance judgment.</b><span>Outdoor and treadmill runs can be viewed together, but EF workload inference remains treadmill-specific. Heat-map deviations are computed within the same run type so an outdoor run is not labeled unusual merely because it differs from treadmill behavior.</span></div>
 {combined.available&&<MultiRunPlot combined={combined}/>}<CompareBars runs={analyzed.filter(r=>r.included)}/><MultiRunHeatMaps runs={analyzed}/>
 <div className="panel table-panel"><div className="panel-head"><div><span>03</span><h2>Run-by-run results</h2></div><small>Mixed activity analysis retained</small></div><div className="table-wrap"><table><thead><tr><th>Run</th><th>Run Type</th><th>Pace</th><th>Run segment</th><th>Run avg HR</th><th>HR drift</th><th>Pace/HRR eff.</th><th>Eff. change</th><th>EF estimate</th><th>Inference</th></tr></thead><tbody>{analyzed.map(r=><tr key={r.id}><td>Run {r.runIndex+1}</td><td><span className={'run-type-tag '+r.runType}>{r.runType==='treadmill'?'Treadmill':'Outdoor'}</span><small className="cell-sub">{r.runTypeOverride?'manual override':`auto · ${r.detectionConfidence}`}</small></td><td>{r.pace}</td><td>{Number.isFinite(r.segment)?formatDuration(r.segment):'—'}</td><td>{Number.isFinite(r.hr)?Math.round(r.hr)+' bpm':'—'}</td><td>{Number.isFinite(r.drift)?(r.drift>=0?'+':'')+r.drift.toFixed(1)+'%':'—'}</td><td>{Number.isFinite(r.efficiencyIndex)?r.efficiencyIndex.toFixed(2):'—'}</td><td>{Number.isFinite(r.efficiencyChange)?(r.efficiencyChange>=0?'+':'')+r.efficiencyChange.toFixed(1)+'%':'—'}</td><td>{r.runType==='treadmill'&&Number.isFinite(r.fitValue)?r.fitValue.toFixed(1):'—'}</td><td>{r.runType==='treadmill'?r.singleConfidence:'Outdoor context'}</td></tr>)}</tbody></table></div></div>
 <div className="disclaimer multi-disclaimer">Mixed-run analysis intentionally separates general running comparisons from treadmill-specific aerobic-fitness inference. Outdoor pace, HR, drift, and running dynamics can contribute to longitudinal pattern analysis, while the combined EF estimate uses only qualifying treadmill observations with corrected treadmill workload inputs.</div></>}{error&&<pre className="error">{error}</pre>}</section>
}

function MetricsGuide(){return <section className="workspace methodology" id="ef-guide"><div className="page-title"><div><div className="eyebrow">METRICS GUIDE</div><h1>What your results are telling you</h1><p>A plain-language guide to the metrics reported by Endurance Forge. For equations, assumptions, and algorithm details, see Methodology.</p></div><div className="pill">PUBLIC BETA</div></div>
<div className="compare-callout"><h2>Is EF Aerobic Fitness Estimate VO₂max?</h2><p><b>It is a treadmill-derived VO₂max-equivalent estimate.</b> Endurance Forge estimates the aerobic capacity consistent with treadmill workload and cardiovascular response. It uses the conventional VO₂max units of mL/kg/min, but oxygen consumption is not directly measured. Treat it as an analytical estimate for tracking and comparison, not as a laboratory measurement or a device-manufacturer value.</p></div>
<div className="panel prose"><h2>VO₂max comparison</h2><div className="table-wrap"><table><thead><tr><th>Metric</th><th>What it represents</th><th>How it is obtained</th></tr></thead><tbody>
<tr><td><b>Laboratory VO₂max</b></td><td>Maximum measured aerobic capacity</td><td>Direct respiratory-gas measurement during a maximal exercise test.</td></tr>
<tr><td><b>Device VO₂max</b></td><td>Estimated VO₂max</td><td>A device manufacturer's proprietary model using exercise and physiological data.</td></tr>
<tr><td><b>EF Aerobic Fitness Estimate</b></td><td>Treadmill-derived VO₂max-equivalent aerobic capacity</td><td>Endurance Forge inference from treadmill workload, heart-rate response, workout structure, and a qualifying stable analysis window.</td></tr>
<tr><td><b>Running O₂ Cost</b></td><td>Oxygen demand of the current treadmill workload</td><td>Calculated from running speed and treadmill grade. This is workload, not VO₂max.</td></tr>
</tbody></table></div>
<h2>EF Aerobic Fitness Estimate</h2><p><b>What it tells you:</b> the aerobic capacity that is consistent with your treadmill workload and cardiovascular response. Higher values generally indicate greater estimated aerobic capacity. The most useful interpretation is repeatability and trend across suitable workouts, not treating one result as an exact physiological measurement.</p><p><b>Why confidence matters:</b> a single submaximal run requires extrapolation. Endurance Forge therefore caps single-run inference confidence at Moderate even when the underlying data quality is High. Multi-run modeling can increase confidence when qualifying runs at meaningfully different workloads agree.</p>
<h2>Multi-run EF Aerobic Fitness Estimate</h2><p><b>What it tells you:</b> whether several model-eligible treadmill runs support one consistent aerobic-capacity estimate. Endurance Forge analyzes each run independently, then combines stable-window workload and HR-reserve observations with a robust model. Runs with weaker data quality, substantial drift, or poor agreement receive less influence. High inference confidence requires corroboration across multiple suitable runs and meaningful workload diversity; it does not mean laboratory validation.</p><p><b>What exclusion does not mean:</b> Endurance Forge does not remove runs because they were slow, difficult, low-performing, or produced an unusually low or high valid EF estimate. Exclusion means the observation does not meet the model's evidence requirements. A technically valid off-day remains part of the combined fitness picture.</p>
<h2>Running O₂ Cost</h2><p><b>What it tells you:</b> the estimated metabolic demand of the running workload in mL/kg/min. It answers “how much oxygen would this workload typically require?” rather than “what is my maximum aerobic capacity?” Grade substantially affects workload, so enter treadmill incline when known.</p>
<h2>HR Drift / Aerobic Decoupling</h2><p><b>What it tells you:</b> whether heart rate rises relative to workload during a sustained running segment. Positive drift means cardiovascular response increased as the run progressed. Lower drift during genuinely comparable workouts can be consistent with better aerobic durability, but temperature, hydration, fatigue, caffeine, illness, stress, and sensor behavior can also affect it.</p><h2>Pace–HR Efficiency</h2><p><b>What it tells you:</b> how much running speed is produced for a given fraction of heart-rate reserve. Endurance Forge reports speed divided by HR-reserve fraction and, more importantly, the percentage change from the first half to the second half of the analyzed segment. The absolute index is not a universal fitness score. Outdoor terrain and wind are not yet normalized, so longitudinal comparisons are most defensible between broadly similar runs.</p><h2>Intensity Summary</h2><p><b>What it tells you:</b> time spent at or above 80% and 90% of heart-rate reserve, the longest continuous ≥80% bout, and peak HR reserve within the analyzed segment. These thresholds are Endurance Forge analytical bands, not a reproduction of Garmin or another device's zone settings.</p><h2>Outdoor Elevation and Power Context</h2><p>When available, Endurance Forge reports approximate ascent/descent from a lightly smoothed altitude trace and descriptive running-power averages/progression. These metrics provide context; they are not yet used to grade-adjust outdoor pace or modify the treadmill EF model.</p>
<h2>HR Reserve</h2><p>Heart-rate reserve places exercise HR between resting HR and known maximum HR. Endurance Forge uses it in the current submaximal fitness model. The highest HR observed in one workout is not automatically treated as your true maximum HR.</p>
<h2>Stable Fitness Window</h2><p>The fitness estimate does not blindly average the entire activity. Endurance Forge first identifies sustained running, trims the walk-to-run HR transition when appropriate, and then searches for a stable workload/HR window. Cardiac drift continues to use the longer comparable running segment.</p>
<h2>Data Quality vs Inference Confidence</h2><p><b>Data Quality</b> describes how suitable and stable the measured data are. <b>Inference Confidence</b> describes how strongly that activity supports the physiological conclusion. High-quality data can still produce only Moderate inference confidence because estimating maximal aerobic capacity from one submaximal run involves uncertainty.</p>
<h2>Virtual Lap Analysis</h2><p><b>What it tells you:</b> how cardiovascular response and running mechanics change across standardized portions of the detected run. Virtual laps use treadmill-corrected distance rather than watch Auto Lap boundaries. The lap length is user-configurable and defaults to 0.25 mile.</p>
<h2>Running Dynamics Change</h2><p><b>What it tells you:</b> whether cadence, stride length, ground-contact time, vertical oscillation, vertical ratio, or ground-contact balance change from the early to late part of the selected running segment. This is descriptive evidence and is intentionally not labeled as a fatigue diagnosis.</p><h2>Environmental Context</h2><p><b>What it tells you:</b> optional indoor temperature and relative-humidity readings are converted to dew point and retained with the run so warm/humid conditions can be considered when interpreting cardiovascular drift. Environmental data are contextual only and do <b>not</b> mathematically raise, lower, correct, or otherwise alter the EF Aerobic Fitness Estimate.</p><h2>Multi-Run Heat Maps</h2><p><b>What they tell you:</b> after at least eight selected runs, the Run Pattern Heat Map highlights measurements that differ from your own historical baseline. A second relationship heat map summarizes pairwise correlations across available metrics. These are exploratory within-run comparisons—not universal good/bad ranges and not evidence of causation.</p>
<h2>Corrected Pace and Speed</h2><p>When you enter treadmill truth, Endurance Forge uses the treadmill distance and time as the authoritative workload values. This is especially useful when watch-estimated indoor distance differs from the treadmill.</p>
<h2>Workout Segmentation</h2><p>Walking, warm-up, sustained running, recovery, and cooldown can have very different cardiovascular responses. Endurance Forge attempts to isolate sustained running before calculating physiological metrics. The automatic selection can be manually overridden for unusual workouts.</p>
</div></section>}

function Methodology(){return <section className="workspace methodology"><div className="page-title"><div><div className="eyebrow">ANALYSIS METHODOLOGY</div><h1>Analysis methodology</h1><p>Endurance Forge separates source-file parsing, treadmill calibration, workout segmentation, workload calculation, physiological inference, and confidence assessment. This page explains how those steps work so the reported metrics can be understood and evaluated. For the physiological derivation, validation literature, and limitations of the aerobic-fitness estimate, see the Scientific Basis technical note.</p></div><div className="pill">TRANSPARENT METHODOLOGY</div></div>
<div className="method-grid"><article><b>01 · Normalize</b><h3>FIT, TCX, GPX</h3><p>Each source format becomes the same timestamped Endurance Forge activity model.</p></article><article><b>02 · Segment</b><h3>Find sustained running</h3><p>A smoothed speed trace identifies a sustained running block and separates slower walking/warm-up when the signal supports it.</p></article><article><b>03 · Infer</b><h3>Use comparable data</h3><p>Drift uses the longer comparable run; aerobic-fitness inference uses a stable workload/HR window inside it.</p></article></div>
<div className="panel prose"><h2>Analysis pipeline</h2><p><b>Raw activity → treadmill truth calibration → sustained-run detection → HR settling trim → stable-window selection → workload O₂ calculation → HR-reserve calculation → single-run EF inference → optional multi-run robust combination → confidence assessment.</b></p>
<p><a className="doc-link" href="/science/">Read EF-TN-001: Scientific Basis of the EF Aerobic Fitness Estimate →</a></p><h2>Running O₂ Cost</h2><p>For level/graded treadmill running, Endurance Forge currently uses the ACSM-style running metabolic relationship:</p><div className="formula">VO₂ workload = 0.2v + 0.9vG + 3.5</div><p>where <b>v</b> is speed in meters per minute and <b>G</b> is fractional treadmill grade (for example, 1% = 0.01). The result is expressed in mL/kg/min. This describes estimated oxygen demand of the workload; it is <b>not</b> VO₂max.</p>
<h2>Heart-rate reserve</h2><div className="formula">HRR fraction = (exercise HR − resting HR) / (maximum HR − resting HR)</div><p>The submaximal model requires user-supplied known maximum HR and resting HR. Activity maximum HR is deliberately not substituted for physiological HRmax.</p>
<h2>EF Aerobic Fitness Estimate</h2><p>The EF Aerobic Fitness Estimate is intended to represent a <b>treadmill-derived VO₂max-equivalent aerobic capacity</b>. The Endurance Forge model relates the stable-window workload above resting metabolic demand to the fraction of heart-rate reserve used:</p><div className="formula">EF estimate = 3.5 + (workload VO₂ − 3.5) / HRR fraction</div><p>This assumes a useful approximately linear submaximal relationship between oxygen reserve and heart-rate reserve. Because that assumption is an approximation and the calculation extrapolates beyond the observed submaximal workload, the result is not directly interchangeable with laboratory VO₂max or any manufacturer's proprietary estimate.</p>
<h2>Multi-run EF model</h2><p>When two or more qualifying activities are selected in Compare Runs, Endurance Forge retains every single-run result and then models all usable stable-window observations together. Define <b>xᵢ</b> as HR-reserve fraction and <b>yᵢ</b> as workload oxygen demand above resting demand:</p><div className="formula">xᵢ = HRRᵢ &nbsp;&nbsp; · &nbsp;&nbsp; yᵢ = workload VO₂ᵢ − 3.5</div><p>The combined model estimates one aerobic-reserve slope <b>β</b> through the physiological resting anchor:</p><div className="formula">β = Σ(wᵢ xᵢ yᵢ) / Σ(wᵢ xᵢ²) &nbsp;&nbsp; and &nbsp;&nbsp; Combined EF = 3.5 + β</div><p>Initial run weights reflect stable-window data quality, single-run inference quality, and the magnitude of aerobic drift. Endurance Forge then applies iterative robust residual weighting so one discordant run has less ability to pull the result away from the relationship supported by the other runs. This is intentionally different from simply averaging the individual EF estimates.</p><h2>Multi-run eligibility and confidence</h2><p>Each selected run receives an explicit evidence classification before combination. <b>Primary</b> evidence has a valid EF observation, at least a 12-minute stable EF window, and no major limitation that requires down-weighting. <b>Supporting</b> evidence remains model-eligible with at least a 10-minute stable EF window, but receives less influence when the window is under the 12-minute Primary target, data quality or single-run inference is Low, workload-normalized drift exceeds 10%, or HR reserve lies near the upper/lower edge of the accepted model range. <b>Excluded</b> evidence is not used when the user deselects the run, no valid EF/workload/HRR observation exists, HRR is outside the current 35–92% range, or the stable EF window is under 10 minutes. These classifications and their specific reasons are shown in Compare Runs.</p><div className="method-principle"><b>Performance-neutral eligibility principle.</b> Evidence eligibility is determined by data adequacy and model applicability, not by whether a run looks good or bad. Pace, the magnitude of a valid EF estimate, and disagreement with the current combined estimate are not exclusion criteria. A technically valid off-day remains evidence. Discordant valid observations stay in the model and may receive less influence only through the published quality/drift weights and robust residual weighting.</div><p><b>High</b> multi-run inference confidence currently requires at least three model-eligible runs including at least two Primary observations, at least three High/Moderate-quality observations, meaningful workload and HRR span, at least two distinct workload levels, and tight run-to-run agreement. <b>Moderate</b> confidence requires at least two suitable corroborating runs with acceptable agreement and some workload separation. Otherwise the combined result remains Low or unavailable.</p><p>Confidence describes internal corroboration of the Endurance Forge model. It does not establish laboratory accuracy. Repeated nearly identical workloads provide less independent information than suitable runs spanning different submaximal workloads, and environmental or physiological factors can shift HR independently of aerobic capacity.</p>
<h2>Stable estimation window</h2><p>After the sustained run and HR-settling transition are identified, Endurance Forge searches candidate windows for consistent treadmill speed and a steadier HR/workload relationship. Longer runs generally allow a 15-minute candidate window; shorter qualifying runs use shorter windows. Candidate scoring penalizes workload variability, HR drift/slope, and late-window placement. The selected window is highlighted on the activity chart.</p>
<h2>HR drift / aerobic decoupling</h2><p>The longer comparable running segment is divided into two portions. Endurance Forge compares heart rate relative to speed so modest workload changes are less likely to masquerade as physiological drift:</p><div className="formula">Drift % = [(HR₂ / speed₂) / (HR₁ / speed₁) − 1] × 100</div><p>If average speed changes materially between halves, the result is labeled aerobic decoupling rather than simple steady-state HR drift.</p><h2>Pace–HR efficiency and intensity exposure</h2><p>When known maximum and resting HR are supplied, Endurance Forge also calculates a relative pace–HR efficiency index:</p><div className="formula">Pace–HR efficiency index = speed (mph) / HRR fraction</div><p>The analyzed segment is divided into halves and the relative percentage change in this index is reported. This is intended for within-run and like-for-like longitudinal interpretation, not as a population fitness score. Endurance Forge also time-weights the HR trace to report exposure at ≥80% and ≥90% HR reserve. These are project-defined analytical thresholds and not device-specific training zones.</p><h2>Outdoor elevation and power context</h2><p>When record-level elevation exists, a short moving average and 0.75 m deadband are applied before accumulating ascent and descent to reduce sample noise. Running power, when present, is summarized over the selected running segment and compared between halves. Neither metric currently modifies the treadmill EF estimate or produces a grade-adjusted outdoor fitness estimate.</p>
<h2>Corrected-distance visualization and virtual laps</h2><p>Endurance Forge reconstructs a corrected distance axis from the calibrated speed trace and scales it to treadmill truth when treadmill distance is supplied. Virtual laps begin at the detected running segment and divide that corrected distance into user-defined intervals. These laps are a visualization and diagnostic layer; they do not independently alter the EF fitness estimate.</p><p>Running-dynamics charts are shown only when supported data are present. Endurance Forge can derive approximate stride length from corrected speed and running cadence when a native step-length value is unavailable. Early-vs-late dynamics are descriptive comparisons and are not presented as a diagnosis of fatigue or injury.</p><h2>Environmental context</h2><p>For indoor/treadmill sessions, users may optionally enter start/end room temperature and relative humidity. Endurance Forge derives dew point using a standard Magnus-form approximation and preserves the values locally with the run. Environment is used only as interpretive and comparative context—for example, when considering whether warm or humid conditions coincided with greater HR drift. It is not a term in the EF aerobic-fitness equation and does not modify the estimated value.</p><h2>Multi-run heat maps</h2><p>Heat maps are withheld until at least eight selected runs are available. The Run Pattern Heat Map compares each measurement with the runner’s own historical distribution using the median and median absolute deviation (MAD); color therefore represents robust standardized deviation from the individual baseline rather than a population-based good/bad threshold. The Metric Relationship Heat Map reports pairwise Pearson correlations when at least six paired observations exist. Correlation cells are exploratory, especially at small sample sizes, and must not be interpreted as causal relationships. Missing data remain neutral rather than being imputed.</p>
<h2>Data quality vs inference confidence</h2><p>Data Quality considers usable duration, sampling, and workload stability in the selected fitness window. Inference Confidence considers whether the physiological extrapolation itself is well supported. A single-activity submaximal estimate is intentionally capped at <b>Moderate</b> inference confidence. Significant drift, workload instability, an unsuitable HR-reserve range, or weak data can reduce it to Low or make the estimate unavailable.</p>
<h2>What Endurance Forge does not claim</h2><p>Endurance Forge does not directly measure oxygen consumption, diagnose fitness or health conditions, reproduce Garmin or another manufacturer's proprietary VO₂max algorithm, or claim laboratory accuracy. Results should be interpreted as analytical estimates rather than direct physiological measurements.</p>
<h2>Privacy and local processing</h2><p>Activity-file parsing and analysis occur in the browser. Raw FIT, TCX, and GPX activity files are not uploaded to an Endurance Forge server by this application. Maximum-HR and resting-HR profile values are stored locally in browser storage.</p>
<h2>Public beta and feedback</h2><p>Endurance Forge is currently in beta while its analytical methods are evaluated across a wider range of runners, workout structures, devices, and treadmill workloads. If a result appears incorrect or unexpected, please report it so the analysis can be reviewed and improved.</p><p><a className="doc-link" href="https://github.com/StatForge-dev/endurance-forge-web/issues" target="_blank" rel="noreferrer">Report feedback or an issue on GitHub ↗</a></p>
<div className="support-card"><div><span className="support-kicker">SUPPORT THE PROJECT</span><h2>Support Endurance Forge</h2><p>Endurance Forge is independently developed and free to use. If you find it useful, you can help support continued development.</p></div><a className="coffee-button" href="https://buymeacoffee.com/enduranceforge" target="_blank" rel="noreferrer">☕ Buy the developer a coffee</a></div>
</div></section>}


function ScientificBasis(){return <section className="workspace methodology science-page"><div className="page-title"><div><div className="eyebrow">EF-TN-001 · TECHNICAL NOTE</div><h1>Scientific basis of the EF Aerobic Fitness Estimate</h1><p>A technical justification of the treadmill workload model, heart-rate-reserve extrapolation, evidence controls, limitations, and the distinction between an analytical estimate and directly measured VO₂max.</p></div><div className="pill">v1.0 · 2026-09-06</div></div>
<div className="panel prose">
<div className="science-status"><b>Scope of the claim</b><span>Endurance Forge does not measure VO₂ and does not claim laboratory equivalence. It estimates a VO₂max-equivalent aerobic capacity from a modeled treadmill oxygen cost and the fraction of heart-rate reserve used during a selected stable submaximal window. The result is therefore a model-based inference whose credibility depends on the validity of both relationships and the quality of the observation.</span></div>
<h2>1. The scientific question</h2><p>The relevant question is not whether a submaximal treadmill effort can ever be used to estimate maximal aerobic capacity; that class of testing is established. The narrower question is whether an ordinary treadmill run can supply a sufficiently controlled submaximal observation to support a useful estimate. Published treadmill protocols have predicted VO₂max from submaximal speed and heart-rate responses, including single-stage jogging tests, while validation studies also show material individual prediction error. Endurance Forge therefore treats the calculation as an estimate with explicit evidence controls rather than as a measurement.</p>
<h2>2. Step 1 — estimate the oxygen cost of the treadmill workload</h2><p>For a detected running segment, Endurance Forge uses the conventional ACSM running metabolic relationship:</p><div className="formula">VO₂work = 0.2v + 0.9vG + 3.5</div><p><b>v</b> is treadmill speed in m·min⁻¹ and <b>G</b> is fractional grade. The output is mL·kg⁻¹·min⁻¹. The three terms represent horizontal locomotion cost, vertical grade cost, and a standardized resting component. This quantity is an <b>estimated oxygen requirement of the workload</b>, not VO₂max and not directly measured oxygen uptake.</p>
<div className="science-caution"><b>Important domain limitation.</b> The conventional ACSM running equation is intended for steady-state running and is commonly described for speeds above about 5 mph (134 m·min⁻¹). Endurance Forge may encounter genuine jogging/running gait below that speed. Published single-stage jogging tests demonstrate that submaximal VO₂max prediction can be performed at speeds beginning around 4.3 mph, but those studies used population regression equations rather than validating the ACSM workload equation at every low jogging speed. Accordingly, Endurance Forge now treats use of the ACSM running workload equation below 5 mph as an extrapolative limitation and lowers single-run inference confidence rather than pretending the workload equation has been validated there.</div>
<p>Equation error is not trivial. Studies have reported both over- and under-prediction of measured oxygen uptake depending on population, intensity, and protocol. A 2022 study of trained runners, for example, found that the ACSM equation underestimated measured VO₂ across several incline conditions up to 8%, while other work during prolonged constant-work running found overprediction. These findings are a reason to expose the workload model and its limitations rather than to present calculated workload VO₂ as measured physiology.</p>
<h2>3. Step 2 — express exercise HR as heart-rate reserve</h2><div className="formula">HRR = (HRexercise − HRrest) / (HRmax − HRrest)</div><p>Heart-rate reserve places the observed exercise HR between an individual resting and maximal anchor. Endurance Forge requires user-supplied resting HR and known maximum HR; it does not substitute the maximum HR seen in the current activity for physiological HRmax.</p><p>Swain and colleagues directly examined treadmill exercise and found that %HRR tracked %VO₂ reserve (%VO₂R) substantially more appropriately than %VO₂max. In 50 adults performing maximal treadmill tests, the mean correlation for %HRR versus %VO₂R was approximately 0.99, with regression close to—but statistically distinguishable from—the identity line. This is strong support for using HRR as an indicator of VO₂ reserve, but it is not proof that the relationship is exactly 1:1 for every runner or every prolonged workout.</p>
<h2>4. Step 3 — derive the Endurance Forge estimate</h2><p>Oxygen-uptake reserve is defined as:</p><div className="formula">VO₂R = VO₂max − VO₂rest</div><p>If the fractional use of oxygen reserve is approximated by fractional HR reserve, then:</p><div className="formula">HRR ≈ (VO₂work − VO₂rest) / (VO₂max − VO₂rest)</div><p>Solving algebraically for VO₂max gives:</p><div className="formula">VO₂max ≈ VO₂rest + (VO₂work − VO₂rest) / HRR</div><p>Using the conventional standardized resting value of 3.5 mL·kg⁻¹·min⁻¹ produces the current Endurance Forge single-run equation:</p><div className="formula">EF = 3.5 + (VO₂work − 3.5) / HRR</div><p>The arithmetic is straightforward. The uncertainty lies in the physiological assumptions used as inputs: modeled workload VO₂, the approximate HRR–VO₂R correspondence, the accuracy of HRmax/resting HR, and whether the selected observation is sufficiently steady for the relationship to be meaningful.</p>
<h2>5. Why a stable window is required</h2><p>The HRR–VO₂R relationship was established from progressive exercise-test observations. It is not perfectly stable during prolonged constant-load exercise. Cunha and colleagues studied 40-minute treadmill bouts at 60%, 70%, and 80% VO₂ reserve and found that HR and VO₂ changed with time and that a 1:1 %HRR–%VO₂R relationship did not hold during those prolonged bouts. Cardiovascular drift can therefore make a later HR value imply a different aerobic requirement even when external workload is unchanged.</p><p>That is the scientific reason Endurance Forge does not simply use whole-run average HR. It searches for a stable running window, measures workload variability and HR drift, and reduces inference confidence when those assumptions are weak. The stable-window algorithm is an Endurance Forge engineering control; its exact thresholds are not themselves claimed to be clinically validated cut points.</p>
<h2>6. Why submaximal estimation is scientifically plausible</h2><p>Submaximal VO₂max prediction is a long-established testing approach. George et al. developed a single-stage treadmill jogging test using a comfortable steady-state jog and HR, with cross-validation SEE around 3.1 mL·kg⁻¹·min⁻¹ in fit young adults. A later multicenter version in 400 adults aged 18–40 reported a PRESS SEE around 2.54 mL·kg⁻¹·min⁻¹. Marsh evaluated an ACSM submaximal treadmill running protocol and reported group-level overestimation of about 3%, but individual SEE of roughly 4 mL·kg⁻¹·min⁻¹. A systematic review identified 43 submaximal prediction equations and concluded that such approaches can be moderately to highly accurate while emphasizing population, exercise mode, medications, exertion, and validation design.</p><p>These studies support the <b>class of inference</b>; they do not validate the exact Endurance Forge equation. Endurance Forge requires its own external validation against breath-by-breath or metabolic-cart VO₂ measurements before a laboratory-accuracy claim would be justified.</p>
<h2>7. Why formal treadmill tests often use multiple stages, higher speeds, or steeper grades</h2><p>Traditional graded protocols deliberately create several distinct workload–response observations and often continue toward high or maximal effort. This improves the ability to characterize the individual workload/HR relationship and, in direct tests, to elicit and measure maximal oxygen uptake. A simple ordinary run usually supplies fewer independent workload levels. Endurance Forge addresses that limitation by treating a single run conservatively and allowing multiple qualifying runs at different workloads to corroborate the relationship.</p><p>Higher speed or grade is therefore not what makes VO₂max estimation mathematically possible. It is one way formal protocols obtain a broad physiological range and stronger identification of the response curve. Endurance Forge instead asks whether repeated, naturally occurring submaximal treadmill runs can provide enough controlled observations for a useful trend-oriented estimate.</p>
<h2>8. Multi-run model</h2><p>For each model-eligible run, define <b>xᵢ = HRRᵢ</b> and <b>yᵢ = VO₂work,i − 3.5</b>. If the reserve relationship is approximately linear through the resting anchor, then <b>yᵢ ≈ βxᵢ</b>, where β estimates aerobic reserve. Endurance Forge fits a weighted slope through that anchor:</p><div className="formula">β = Σ(wᵢxᵢyᵢ) / Σ(wᵢxᵢ²) &nbsp;&nbsp; ; &nbsp;&nbsp; EFcombined = 3.5 + β</div><p>Weights reflect evidence quality and drift, followed by robust residual weighting so a discordant but technically valid observation has reduced leverage rather than being discarded merely because it represents a poor day. This is a project-specific estimator, not a published clinical protocol. Its purpose is to reduce dependence on any single submaximal observation and to make disagreement visible.</p>
<h2>9. Why this is not already a simple universal watch calculation</h2><p>The equation is simple only after its inputs are trustworthy. Indoor watches may estimate rather than directly know belt speed and grade; treadmill calibration can be imperfect; running economy varies between people; HR drifts with duration, temperature, hydration, fatigue and intensity; HRmax can be misestimated; and ordinary workouts do not necessarily provide controlled steady-state stages. Outdoors, grade, wind, surface and pace changes add further uncertainty. A simple formula applied to uncertain inputs can create false precision.</p><p>Endurance Forge's approach is therefore not a claim to have discovered a new physiological law. It is an attempt to <b>operationalize established submaximal relationships for treadmill activity files while exposing the assumptions, selecting more defensible observations, and reporting evidence strength.</b></p>
<h2>10. Known limitations and falsifiable claims</h2><div className="claim-grid"><div><b>Supported foundation</b><span>Treadmill speed/grade can model oxygen cost; HRR is related to VO₂ reserve; submaximal treadmill responses can predict VO₂max at the group/model level.</span></div><div><b>Not yet established</b><span>The exact Endurance Forge estimator's bias, limits of agreement, and test–retest error against directly measured VO₂max across ages, fitness levels, gait speeds, devices, and treadmill grades.</span></div><div><b>Current use</b><span>Trend-oriented analytical estimate with explicit confidence and multi-run corroboration.</span></div><div><b>Required validation</b><span>Prospective comparison against metabolic-cart measurements, with preregistered error metrics and subgroup analysis.</span></div></div>
<h2>11. Interpretation boundaries</h2><p>A laboratory VO₂max test measures respiratory gas exchange during a maximal protocol. Endurance Forge does not. The EF value should therefore be described as an <b>EF Aerobic Fitness Estimate</b> or <b>treadmill-derived VO₂max-equivalent estimate</b>, never as a measured VO₂max. Agreement across repeated runs increases confidence in internal consistency, not proof of external accuracy.</p>
<h2>12. References</h2><ol className="references">
<li>Swain DP, Leutholtz BC, King ME, Haas LA, Branch JD. Relationship between % heart rate reserve and % VO₂ reserve in treadmill exercise. <i>Med Sci Sports Exerc.</i> 1998;30(2):318–321. DOI 10.1097/00005768-199802000-00022. <a href="https://pubmed.ncbi.nlm.nih.gov/9502363/" target="_blank" rel="noreferrer">PubMed ↗</a></li>
<li>Cunha FA, Midgley AW, Monteiro WD, Campos FK, Farinatti PTV. The relationship between oxygen uptake reserve and heart rate reserve is affected by intensity and duration during aerobic exercise at constant work rate. <i>Appl Physiol Nutr Metab.</i> 2011;36(6):839–847. DOI 10.1139/h11-100. <a href="https://pubmed.ncbi.nlm.nih.gov/22034854/" target="_blank" rel="noreferrer">PubMed ↗</a></li>
<li>Marsh CE. Evaluation of the American College of Sports Medicine submaximal treadmill running test for predicting VO₂max. <i>J Strength Cond Res.</i> 2012;26(2):548–554. DOI 10.1519/JSC.0b013e3181bac56e. <a href="https://pubmed.ncbi.nlm.nih.gov/22262016/" target="_blank" rel="noreferrer">PubMed ↗</a></li>
<li>Evans HJL, Ferrar KE, Smith AE, Parfitt G, Eston RG. A systematic review of methods to predict maximal oxygen uptake from submaximal, open circuit spirometry in healthy adults. <i>J Sci Med Sport.</i> 2015;18(2):183–188. DOI 10.1016/j.jsams.2014.03.006. <a href="https://pubmed.ncbi.nlm.nih.gov/24721146/" target="_blank" rel="noreferrer">PubMed ↗</a></li>
<li>George JD, Vehrs PR, Allsen PE, Fellingham GW, Fisher AG. Development of a submaximal treadmill jogging test for fit college-aged individuals. <i>Med Sci Sports Exerc.</i> 1993;25(5):643–647. <a href="https://pubmed.ncbi.nlm.nih.gov/8492693/" target="_blank" rel="noreferrer">PubMed ↗</a></li>
<li>George JD et al. Submaximal treadmill exercise test to predict VO₂max in fit adults. <i>Measurement in Physical Education and Exercise Science.</i> 2007. DOI 10.1080/10913670701294047. <a href="https://www.tandfonline.com/doi/full/10.1080/10913670701294047" target="_blank" rel="noreferrer">Article ↗</a></li>
<li>Foreman NA, Lee EJ, Lundstrom CJ. Assessment of a treadmill speed incline conversion chart: a validation study. <i>Int J Sports Physiol Perform.</i> 2022;17(7):1030–1036. DOI 10.1123/ijspp.2021-0021. <a href="https://pubmed.ncbi.nlm.nih.gov/35299154/" target="_blank" rel="noreferrer">PubMed ↗</a></li>
<li>Kokkinos P, Kaminsky LA, Arena R, Zhang J, Myers J. New generalized equation for predicting maximal oxygen uptake from the FRIEND registry. <i>Am J Cardiol.</i> 2017;120(4):688–692. DOI 10.1016/j.amjcard.2017.05.037. <a href="https://pubmed.ncbi.nlm.nih.gov/28676154/" target="_blank" rel="noreferrer">PubMed ↗</a></li>
<li>Tanaka H, Monahan KD, Seals DR. Age-predicted maximal heart rate revisited. <i>J Am Coll Cardiol.</i> 2001;37(1):153–156. DOI 10.1016/S0735-1097(00)01054-8. <a href="https://pubmed.ncbi.nlm.nih.gov/11153730/" target="_blank" rel="noreferrer">PubMed ↗</a></li>
<li>Mayhew JL. Oxygen cost and energy expenditure of running in trained runners. <i>Br J Sports Med.</i> 1977;11(3):116–121. DOI 10.1136/bjsm.11.3.116. <a href="https://pubmed.ncbi.nlm.nih.gov/922272/" target="_blank" rel="noreferrer">PubMed ↗</a></li>
</ol>
<p className="viz-note">Technical note EF-TN-001 v1.0. References are provided to make the physiological basis and contrary/limiting evidence independently inspectable. Publication of a reference here does not imply that the authors validated Endurance Forge.</p>
</div></section>}

function App(){
 const[page,setPage]=useState(pageFromLocation);
 const go=(next)=>{const path=pagePaths[next]||'/';if(window.location.pathname!==path)window.history.pushState({page:next},'',path);setPage(next);window.scrollTo({top:0,behavior:'auto'})};
 useEffect(()=>{const onPop=()=>setPage(pageFromLocation());window.addEventListener('popstate',onPop);return()=>window.removeEventListener('popstate',onPop)},[]);
 useEffect(()=>{const meta=pageMeta[page]||pageMeta.home;document.title=meta.title;let d=document.querySelector('meta[name="description"]');if(d)d.setAttribute('content',meta.description);let c=document.querySelector('link[rel="canonical"]');if(c)c.setAttribute('href','https://endurance-forge.com'+(pagePaths[page]||'/'));let og=document.querySelector('meta[property="og:url"]');if(og)og.setAttribute('content','https://endurance-forge.com'+(pagePaths[page]||'/'));},[page]);
 const body=page==='home'?<Home go={go}/>:page==='analyze'?<Analyze/>:page==='compare'?<Compare/>:page==='guide'?<MetricsGuide/>:page==='method'?<Methodology/>:<ScientificBasis/>;
 return <Shell page={page} go={go}>{body}</Shell>
}
createRoot(document.getElementById('root')).render(<App/>);
